/// Turn-side application contract shared by ordinary and durable owners.
#[async_trait::async_trait]
pub(crate) trait MountedTurnHarness<I = Turn>: Send + Sync + 'static {
    type CallProps: ?Sized + Sync + 'static;
    type TurnProps: Send + Sync + 'static;
    type Source: ?Sized + Sync;
    type ContextState: Clone + Send + Sync + 'static;
    type Channels: TurnChannels;
    type CaptureError: Error + Send + Sync + 'static;

    async fn capture_turn_props(
        &self,
        context: TurnCaptureContext<'_, I, Self::ContextState, Self::CallProps, Self::Source>,
    ) -> Result<Self::TurnProps, Self::CaptureError>;

    fn user(&self, context: UserTurnContext<'_, Self::TurnProps>) -> UserView;

    /// Fixed upper bound for a logical call's `Wait`/`Continue` chain.
    ///
    /// Compatibility-only harnesses that do not declare a policy remain
    /// single-turn. The public captured definition overrides this from its
    /// author-owned [`TurnLoopPolicy`].
    fn turn_loop_policy(&self) -> TurnLoopPolicy {
        TurnLoopPolicy::ONE_TURN
    }
}

/// Compatibility owner with a process-local System callback.
pub(crate) trait MountedHarness<I = Turn>: MountedTurnHarness<I> {
    type MountProps: ?Sized + Send + Sync + 'static;

    fn epoch_contract_id(mount_props: &Self::MountProps) -> EpochContractId;

    fn system(
        context: SystemMountContext<'_, Self::MountProps>,
    ) -> SystemView<Self::Channels, Self::TurnProps>;
}

/// Marker for a durable owner whose complete ordered System is binding-owned.
pub(crate) trait DurableMountedHarness<I = Turn>: MountedTurnHarness<I> {}

/// Adapter from the public POM/capture definition to the private owner trait.
///
/// This is the only harness implementation used by the public mounted path;
/// provider or persistence factories cannot substitute parallel System/User
/// callbacks.
pub(crate) struct DefinitionMountedHarness<C, Capture, I>
where
    C: TurnChannels,
    Capture: MountedTurnCapture<Transcript = I>,
{
    definition: Arc<CapturedMountedHarnessDefinition<C, Capture, I>>,
}

#[async_trait::async_trait]
impl<C, Capture, I> MountedTurnHarness<I> for DefinitionMountedHarness<C, Capture, I>
where
    C: TurnChannels,
    Capture: MountedTurnCapture<Transcript = I>,
    I: Send + Sync + 'static,
{
    type CallProps = Capture::CallProps;
    type TurnProps = Capture::TurnProps;
    type Source = Capture::Source;
    type ContextState = Capture::ContextState;
    type Channels = C;
    type CaptureError = Capture::Error;

    async fn capture_turn_props(
        &self,
        context: TurnCaptureContext<'_, I, Self::ContextState, Self::CallProps, Self::Source>,
    ) -> Result<Self::TurnProps, Self::CaptureError> {
        self.definition.capture_turn_props(context).await
    }

    fn user(&self, context: UserTurnContext<'_, Self::TurnProps>) -> UserView {
        self.definition.render_user(context)
    }

    fn turn_loop_policy(&self) -> TurnLoopPolicy {
        self.definition.turn_loop_policy()
    }
}

impl<C, Capture, I> DurableMountedHarness<I> for DefinitionMountedHarness<C, Capture, I>
where
    C: TurnChannels,
    Capture: MountedTurnCapture<Transcript = I>,
    I: Send + Sync + 'static,
{
}

/// Runtime-liveness lease shared by the mounted owner and every detached actor.
#[derive(Clone)]
pub(crate) struct MountedRuntime {
    inner: Arc<MountedRuntimeInner>,
}

/// Explicit deadlines owned by one mounted runtime.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct MountedRuntimePolicy {
    context_preparation_timeout: std::time::Duration,
    provider_cancellation_grace: std::time::Duration,
}

impl MountedRuntimePolicy {
    pub(crate) fn new(
        context_preparation_timeout: std::time::Duration,
        provider_cancellation_grace: std::time::Duration,
    ) -> Self {
        Self {
            context_preparation_timeout,
            provider_cancellation_grace,
        }
    }

    pub(crate) fn context_preparation_timeout(self) -> std::time::Duration {
        self.context_preparation_timeout
    }

    pub(crate) fn provider_cancellation_grace(self) -> std::time::Duration {
        self.provider_cancellation_grace
    }
}

impl MountedRuntime {
    /// Move a runtime onto a keeper thread and return its clonable lease.
    ///
    /// The keeper drives current-thread runtimes as well as retaining
    /// multi-thread runtimes. When the last lease disappears, it shuts down and
    /// drops the runtime outside every Tokio async context.
    pub(crate) fn new(runtime: Runtime, policy: MountedRuntimePolicy) -> std::io::Result<Self> {
        let handle = runtime.handle().clone();
        let (shutdown, shutdown_receiver) = oneshot::channel();
        std::thread::Builder::new()
            .name("agentview-mounted-runtime".to_owned())
            .spawn(move || {
                runtime.block_on(async {
                    let _ = shutdown_receiver.await;
                });
                drop(runtime);
            })?;
        Ok(Self {
            inner: Arc::new(MountedRuntimeInner {
                handle,
                policy,
                shutdown: Some(shutdown),
            }),
        })
    }

    /// Borrow a caller-owned Tokio runtime without taking shutdown ownership.
    ///
    /// The host that supplied `handle` must keep its [`Runtime`] alive and, for
    /// a current-thread runtime, driven for all mounted owners and their
    /// detached work. Unlike [`Self::new`], dropping this lease never attempts
    /// to stop the supplied runtime.
    pub(crate) fn from_handle(handle: Handle, policy: MountedRuntimePolicy) -> Self {
        Self {
            inner: Arc::new(MountedRuntimeInner {
                handle,
                policy,
                shutdown: None,
            }),
        }
    }

    pub(crate) fn handle(&self) -> &Handle {
        &self.inner.handle
    }

    pub(crate) fn policy(&self) -> MountedRuntimePolicy {
        self.inner.policy
    }
}

struct MountedRuntimeInner {
    handle: Handle,
    policy: MountedRuntimePolicy,
    shutdown: Option<oneshot::Sender<()>>,
}

impl Drop for MountedRuntimeInner {
    fn drop(&mut self) {
        if let Some(shutdown) = self.shutdown.take() {
            let _ = shutdown.send(());
        }
    }
}

impl fmt::Debug for MountedRuntime {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("MountedRuntime")
            .finish_non_exhaustive()
    }
}

/// A mounted session already contains a different logical System prompt.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("mounted session System does not match the candidate epoch")]
pub(crate) struct MountedSessionSystemMismatch;

/// Failure while constructing one authoritative mounted owner.
#[derive(Debug, thiserror::Error)]
pub(crate) enum MountedAgentMountError {
    #[error(transparent)]
    System(#[from] SystemMountError),

    #[error("provider epoch attachment failed: {source}")]
    ProviderEpoch {
        #[source]
        source: Box<dyn Error + Send + Sync + 'static>,
    },

    #[error(transparent)]
    Session(#[from] MountedSessionSystemMismatch),
}

/// Failure while producing the one durable System artifact.
///
/// System compilation and the durable declaration projection are one atomic
/// mount operation. Keeping both errors here prevents the lifecycle API from
/// pretending that a manifest projection failure is a POM render failure.
#[derive(Debug, thiserror::Error)]
enum DurableSystemMountError {
    #[error(transparent)]
    System(#[from] SystemMountError),

    #[error(transparent)]
    RuntimeContract(#[from] DurableRuntimeContractError),

    #[error(transparent)]
    ProviderDispatcherRegistry(#[from] ProviderDispatcherRegistryError),
}

impl MountedAgentMountError {
    fn provider_epoch(source: impl Error + Send + Sync + 'static) -> Self {
        Self::ProviderEpoch {
            source: Box::new(source),
        }
    }
}

/// The previous turn lost its cleanup owner before acknowledgement.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
#[error("mounted agent is unavailable because prior cleanup was not acknowledged")]
pub(crate) struct MountedAgentCleanupUnacknowledged;

/// The durable store rejected the last candidate because this owner's session
/// revision is stale. Calls remain disabled until the host atomically reloads
/// an authoritative session and revision.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
#[error("mounted agent must reload its durable session before accepting another call")]
pub(crate) struct MountedAgentReloadRequired;

/// A mounted owner cannot acquire a call lane while cleanup or reload is
/// outstanding.
#[derive(Debug, Clone, Copy, PartialEq, Eq, thiserror::Error)]
pub(crate) enum MountedAgentUnavailable {
    #[error(transparent)]
    CleanupUnacknowledged(#[from] MountedAgentCleanupUnacknowledged),

    #[error(transparent)]
    ReloadRequired(#[from] MountedAgentReloadRequired),
}

/// Reconfiguration either observes a poisoned owner or rejects its pure rebase.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum MountedReconfigureError<E> {
    CleanupUnacknowledged(MountedAgentCleanupUnacknowledged),
    ReloadRequired(MountedAgentReloadRequired),
    PendingContinuation(DurableCallId),
    GenerationExhausted,
    ProviderEpochAttach { message: String },
    Rebase(E),
}

/// Failure while atomically replacing stale mounted session state.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub(crate) enum MountedReloadError {
    #[error(transparent)]
    CleanupUnacknowledged(#[from] MountedAgentCleanupUnacknowledged),

    #[error(transparent)]
    Session(#[from] MountedSessionSystemMismatch),

    #[error("mounted agent generation is exhausted")]
    GenerationExhausted,
}

/// Failure while installing a persistence-activated replacement epoch into the
/// local owner. The durable store has already performed the authoritative
/// session/epoch transition; this only updates the process-local runtime after
/// its preflight checks have made failure impossible in normal operation.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
enum MountedDurableEpochInstallError {
    #[error(transparent)]
    CleanupUnacknowledged(#[from] MountedAgentCleanupUnacknowledged),

    #[error(transparent)]
    ReloadRequired(#[from] MountedAgentReloadRequired),

    #[error(transparent)]
    Session(#[from] MountedSessionSystemMismatch),

    #[error("cannot replace the mounted epoch while call `{0}` remains active")]
    PendingContinuation(DurableCallId),

    #[error("mounted agent generation is exhausted")]
    GenerationExhausted,
}

