/// Acknowledged local attempt cleanup after provider cancellation.
///
/// When `provider_join_timed_out` is true, the provider future did not
/// acknowledge exit before the owner's grace deadline. The local attempt is
/// aborted, but the mounted agent is poisoned and cannot start another call.
#[derive(Debug)]
pub(crate) struct ManagedProviderCancellation<E> {
    reason: ProviderCancellationReason,
    cursor: ProviderCancellationCursorDisposition,
    provider_error: Option<E>,
    provider_join_timed_out: bool,
    abort: ManagedAttemptAbort,
}

impl<E> ManagedProviderCancellation<E> {
    pub(crate) fn reason(&self) -> ProviderCancellationReason {
        self.reason
    }

    /// Provider-owned cursor authority retained after joined cancellation.
    ///
    /// The current local host intentionally does not settle the durable call
    /// from this value. The exact-lease settlement/recovery owner will consume
    /// it only after validating the call fence and publication state.
    pub(crate) fn cursor_disposition(&self) -> &ProviderCancellationCursorDisposition {
        &self.cursor
    }

    pub(crate) fn provider_error(&self) -> Option<&E> {
        self.provider_error.as_ref()
    }

    pub(crate) fn provider_join_timed_out(&self) -> bool {
        self.provider_join_timed_out
    }

    pub(crate) fn abort(&self) -> &ManagedAttemptAbort {
        &self.abort
    }
}

/// Terminal outcome of the provider task owned by the mounted runtime.
#[derive(Debug)]
pub(crate) enum ManagedProviderExecutionOutcome<
    I,
    Version,
    StoreError,
    ProviderError,
    PublicationInput = (),
> where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    Completed(ManagedProviderCompletion<I, Version, StoreError, PublicationInput>),
    Cancelled(ManagedProviderCancellation<ProviderError>),
}

/// Provider failure after the owner has joined execution and attempted cleanup.
#[derive(Debug)]
pub(crate) enum ManagedProviderExecutionError<E>
where
    E: Error + Send + Sync + 'static,
{
    Provider {
        source: E,
        abort: ManagedAttemptAbort,
    },
    Cleanup {
        provider_error: Option<E>,
        source: ManagedAttemptError,
    },
    Attempt(ManagedAttemptError),
    ControlStopped,
}

impl<E> ManagedProviderExecutionError<E>
where
    E: Error + Send + Sync + 'static,
{
    pub(crate) fn provider_error(&self) -> Option<&E> {
        match self {
            Self::Provider { source, .. } => Some(source),
            Self::Cleanup { provider_error, .. } => provider_error.as_ref(),
            Self::Attempt(_) | Self::ControlStopped => None,
        }
    }

    pub(crate) fn abort(&self) -> Option<&ManagedAttemptAbort> {
        match self {
            Self::Provider { abort, .. } => Some(abort),
            Self::Cleanup { .. } | Self::Attempt(_) | Self::ControlStopped => None,
        }
    }
}

impl<E> fmt::Display for ManagedProviderExecutionError<E>
where
    E: Error + Send + Sync + 'static,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Provider { source, .. } => {
                write!(formatter, "mounted provider execution failed: {source}")
            }
            Self::Cleanup { source, .. } => {
                write!(formatter, "mounted provider cleanup failed: {source}")
            }
            Self::Attempt(source) => write!(formatter, "mounted attempt failed: {source}"),
            Self::ControlStopped => {
                formatter.write_str("mounted provider execution owner stopped unexpectedly")
            }
        }
    }
}

impl<E> Error for ManagedProviderExecutionError<E>
where
    E: Error + Send + Sync + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Provider { source, .. } => Some(source),
            Self::Cleanup { source, .. } | Self::Attempt(source) => Some(source),
            Self::ControlStopped => None,
        }
    }
}

type ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput> = Result<
    ManagedProviderExecutionOutcome<I, Version, StoreError, ProviderError, PublicationInput>,
    ManagedProviderExecutionError<ProviderError>,
>;

type BoxManagedProviderStartError = Box<dyn Error + Send + Sync>;

struct ManagedCallCheckpoint<Version> {
    call_id: DurableCallId,
    state: Option<DurableCallState>,
    session_revision: Version,
}

#[async_trait::async_trait]
trait ManagedProviderStartGate<Version>: Send
where
    Version: Send,
{
    async fn mark_provider_started(
        &mut self,
    ) -> Result<ManagedCallCheckpoint<Version>, BoxManagedProviderStartError>;

    async fn abandon_unstarted(
        &mut self,
    ) -> Result<ManagedCallCheckpoint<Version>, BoxManagedProviderStartError>;

    fn provider_spawned(&mut self);
}

#[derive(Debug, thiserror::Error)]
#[error("{0}")]
struct ManagedProviderStartInvariant(&'static str);

/// Failure before a final mounted provider operation can start.
#[derive(Debug)]
pub(crate) enum ManagedMountedTurnPrepareError<ProviderError, StartError, CaptureError = Infallible>
where
    ProviderError: Error + Send + Sync + 'static,
    StartError: Error + Send + Sync + 'static,
    CaptureError: Error + Send + Sync + 'static,
{
    Capture(CaptureError),
    Component(ComponentError),
    Resolution(PomResolutionError),
    Render(PomRenderError),
    Provider(ProviderError),
    Attempt(StartError),
    Cancelled {
        reason: ProviderCancellationReason,
    },
    ProviderAdmission(BoxManagedProviderStartError),
    ProviderAdmissionCleanup {
        source: BoxManagedProviderStartError,
        cleanup: ManagedAttemptError,
    },
    ReservationCleanup {
        preparation: BoxManagedProviderStartError,
        cleanup: BoxManagedProviderStartError,
    },
    ContextPreparationTimeout {
        timeout: std::time::Duration,
    },
    ReplacementLimit {
        limit: usize,
    },
}

impl<ProviderError, StartError, CaptureError>
    ManagedMountedTurnPrepareError<ProviderError, StartError, CaptureError>
where
    ProviderError: Error + Send + Sync + 'static,
    StartError: Error + Send + Sync + 'static,
    CaptureError: Error + Send + Sync + 'static,
{
    /// These variants return only after `abandon_unstarted` has restored the
    /// call's stable boundary. Provider admission and reservation-cleanup
    /// failures stay indeterminate because their durable fence may be unknown.
    fn did_not_start_provider(&self) -> bool {
        matches!(
            self,
            Self::Capture(_)
                | Self::Component(_)
                | Self::Resolution(_)
                | Self::Render(_)
                | Self::Provider(_)
                | Self::Attempt(_)
                | Self::ContextPreparationTimeout { .. }
                | Self::ReplacementLimit { .. }
        )
    }
}

impl<ProviderError, StartError, CaptureError> fmt::Display
    for ManagedMountedTurnPrepareError<ProviderError, StartError, CaptureError>
where
    ProviderError: Error + Send + Sync + 'static,
    StartError: Error + Send + Sync + 'static,
    CaptureError: Error + Send + Sync + 'static,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Capture(source) => {
                write!(formatter, "mounted User input capture failed: {source}")
            }
            Self::Component(source) => {
                write!(formatter, "mounted User preparation failed: {source}")
            }
            Self::Resolution(source) => {
                write!(formatter, "mounted User POM resolution failed: {source}")
            }
            Self::Render(source) => {
                write!(formatter, "mounted User POM rendering failed: {source}")
            }
            Self::Provider(source) => {
                write!(
                    formatter,
                    "mounted provider context preparation failed: {source}"
                )
            }
            Self::Attempt(source) => write!(formatter, "mounted attempt start failed: {source}"),
            Self::Cancelled { reason } => {
                write!(
                    formatter,
                    "mounted turn preparation was cancelled: {reason:?}"
                )
            }
            Self::ProviderAdmission(source) => {
                write!(formatter, "mounted provider admission failed: {source}")
            }
            Self::ProviderAdmissionCleanup { source, cleanup } => write!(
                formatter,
                "mounted provider admission failed: {source}; attempt cleanup failed: {cleanup}"
            ),
            Self::ReservationCleanup {
                preparation,
                cleanup,
            } => write!(
                formatter,
                "mounted preparation failed: {preparation}; reservation cleanup failed: {cleanup}"
            ),
            Self::ContextPreparationTimeout { timeout } => write!(
                formatter,
                "mounted provider context preparation exceeded {timeout:?}"
            ),
            Self::ReplacementLimit { limit } => write!(
                formatter,
                "mounted turn exceeded its context replacement limit {limit}"
            ),
        }
    }
}

impl<ProviderError, StartError, CaptureError> Error
    for ManagedMountedTurnPrepareError<ProviderError, StartError, CaptureError>
where
    ProviderError: Error + Send + Sync + 'static,
    StartError: Error + Send + Sync + 'static,
    CaptureError: Error + Send + Sync + 'static,
{
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Capture(source) => Some(source),
            Self::Component(source) => Some(source),
            Self::Resolution(source) => Some(source),
            Self::Render(source) => Some(source),
            Self::Provider(source) => Some(source),
            Self::Attempt(source) => Some(source),
            Self::Cancelled { .. } => None,
            Self::ProviderAdmission(source) => Some(source.as_ref()),
            Self::ProviderAdmissionCleanup { source, .. } => Some(source.as_ref()),
            Self::ReservationCleanup { preparation, .. } => Some(preparation.as_ref()),
            Self::ContextPreparationTimeout { .. } | Self::ReplacementLimit { .. } => None,
        }
    }
}

