/// Cancellation-safe handle for one already-started mounted provider operation.
#[must_use = "a managed provider execution must be completed or explicitly cancelled"]
pub(crate) struct ManagedProviderExecution<
    I,
    Version,
    StoreError,
    ProviderError,
    PublicationInput = (),
> where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    cancellation: Option<oneshot::Sender<ProviderCancellationReason>>,
    completion: oneshot::Receiver<
        ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput>,
    >,
}

impl<I, Version, StoreError, ProviderError, PublicationInput>
    ManagedProviderExecution<I, Version, StoreError, ProviderError, PublicationInput>
where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    pub(crate) async fn complete(
        mut self,
    ) -> ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput> {
        let result = (&mut self.completion)
            .await
            .map_err(|_| ManagedProviderExecutionError::ControlStopped)?;
        self.cancellation.take();
        result
    }

    async fn complete_or_cancel_when<F>(
        mut self,
        cancellation_requested: F,
        reason: ProviderCancellationReason,
    ) -> ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput>
    where
        F: std::future::Future<Output = ()>,
    {
        tokio::pin!(cancellation_requested);
        let (result, cancellation_requested) = tokio::select! {
            biased;
            () = &mut cancellation_requested => {
                if let Some(cancellation) = self.cancellation.take() {
                    let _ = cancellation.send(reason);
                }
                ((&mut self.completion).await, true)
            }
            result = &mut self.completion => (result, false),
        };
        let result = result.map_err(|_| ManagedProviderExecutionError::ControlStopped)?;
        self.cancellation.take();
        if !cancellation_requested {
            return result;
        }
        match result? {
            ManagedProviderExecutionOutcome::Completed(completion) => {
                let (_, _, finished) = completion.into_parts();
                cancel_finished(
                    finished,
                    reason,
                    ProviderCancellationCursorDisposition::Indeterminate,
                    None,
                    false,
                )
                .await
            }
            cancelled @ ManagedProviderExecutionOutcome::Cancelled(_) => Ok(cancelled),
        }
    }

    pub(crate) async fn cancel(
        mut self,
        reason: ProviderCancellationReason,
    ) -> ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput> {
        if let Some(cancellation) = self.cancellation.take() {
            let _ = cancellation.send(reason);
        }
        let result = (&mut self.completion)
            .await
            .map_err(|_| ManagedProviderExecutionError::ControlStopped)??;
        match result {
            ManagedProviderExecutionOutcome::Completed(completion) => {
                let (_, _, finished) = completion.into_parts();
                cancel_finished(
                    finished,
                    reason,
                    ProviderCancellationCursorDisposition::Indeterminate,
                    None,
                    false,
                )
                .await
            }
            cancelled @ ManagedProviderExecutionOutcome::Cancelled(_) => Ok(cancelled),
        }
    }
}

impl<I, ContextState, Version, StoreError, ProviderError, PublicationInput>
    ManagedMountedTurn<I, ContextState, Version, StoreError, ProviderError, PublicationInput>
where
    I: Send + 'static,
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    pub(crate) fn epoch_id(&self) -> HarnessEpochId {
        self.epoch_id
    }

    pub(crate) fn turn_instance_id(&self) -> TurnInstanceId {
        self.turn_instance_id
    }

    pub(crate) fn request(&self) -> &MountedProviderRequest<I> {
        &self.request
    }

    pub(crate) fn draft_session(&self) -> &AgentSession<I, ContextState> {
        &self.draft_session
    }

    pub(crate) fn next_user_document_cursor(&self) -> &UserDocumentCursor {
        &self.next_user_document_cursor
    }

    pub(crate) async fn complete(
        self,
    ) -> Result<
        ManagedMountedTurnOutcome<
            I,
            ContextState,
            Version,
            StoreError,
            ProviderError,
            PublicationInput,
        >,
        ManagedProviderExecutionError<ProviderError>,
    > {
        let Self {
            epoch_id,
            turn_instance_id,
            request,
            draft_session,
            next_user_document_cursor,
            execution,
        } = self;
        match execution.complete().await? {
            ManagedProviderExecutionOutcome::Completed(provider) => Ok(
                ManagedMountedTurnOutcome::Completed(ManagedMountedTurnCompletion {
                    epoch_id,
                    turn_instance_id,
                    request,
                    draft_session,
                    next_user_document_cursor,
                    provider,
                }),
            ),
            ManagedProviderExecutionOutcome::Cancelled(cancellation) => {
                Ok(ManagedMountedTurnOutcome::Cancelled {
                    epoch_id,
                    turn_instance_id,
                    cancellation,
                })
            }
        }
    }

    async fn complete_or_cancel_when<F>(
        self,
        cancellation_requested: F,
        reason: ProviderCancellationReason,
    ) -> Result<
        ManagedMountedTurnOutcome<
            I,
            ContextState,
            Version,
            StoreError,
            ProviderError,
            PublicationInput,
        >,
        ManagedProviderExecutionError<ProviderError>,
    >
    where
        F: std::future::Future<Output = ()>,
    {
        let Self {
            epoch_id,
            turn_instance_id,
            request,
            draft_session,
            next_user_document_cursor,
            execution,
        } = self;
        match execution
            .complete_or_cancel_when(cancellation_requested, reason)
            .await?
        {
            ManagedProviderExecutionOutcome::Completed(provider) => Ok(
                ManagedMountedTurnOutcome::Completed(ManagedMountedTurnCompletion {
                    epoch_id,
                    turn_instance_id,
                    request,
                    draft_session,
                    next_user_document_cursor,
                    provider,
                }),
            ),
            ManagedProviderExecutionOutcome::Cancelled(cancellation) => {
                Ok(ManagedMountedTurnOutcome::Cancelled {
                    epoch_id,
                    turn_instance_id,
                    cancellation,
                })
            }
        }
    }

    pub(crate) async fn cancel(
        self,
        reason: ProviderCancellationReason,
    ) -> Result<
        ManagedMountedTurnOutcome<
            I,
            ContextState,
            Version,
            StoreError,
            ProviderError,
            PublicationInput,
        >,
        ManagedProviderExecutionError<ProviderError>,
    > {
        let Self {
            epoch_id,
            turn_instance_id,
            execution,
            ..
        } = self;
        match execution.cancel(reason).await? {
            ManagedProviderExecutionOutcome::Cancelled(cancellation) => {
                Ok(ManagedMountedTurnOutcome::Cancelled {
                    epoch_id,
                    turn_instance_id,
                    cancellation,
                })
            }
            ManagedProviderExecutionOutcome::Completed(provider) => {
                let (_, _, finished) = provider.into_parts();
                let cancellation = finished
                    .abort(BindingAbortReason::Cancelled)
                    .await
                    .map_err(ManagedProviderExecutionError::Attempt)?;
                Ok(ManagedMountedTurnOutcome::Cancelled {
                    epoch_id,
                    turn_instance_id,
                    cancellation: ManagedProviderCancellation {
                        reason,
                        cursor: ProviderCancellationCursorDisposition::Indeterminate,
                        provider_error: None,
                        provider_join_timed_out: false,
                        abort: cancellation,
                    },
                })
            }
        }
    }
}

impl<I, Version, StoreError, ProviderError, PublicationInput> fmt::Debug
    for ManagedProviderExecution<I, Version, StoreError, ProviderError, PublicationInput>
where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ManagedProviderExecution")
            .finish_non_exhaustive()
    }
}

impl<I, Version, StoreError, ProviderError, PublicationInput> Drop
    for ManagedProviderExecution<I, Version, StoreError, ProviderError, PublicationInput>
where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    fn drop(&mut self) {
        if let Some(cancellation) = self.cancellation.take() {
            let _ = cancellation.send(ProviderCancellationReason::OwnerCancelled);
        }
    }
}

#[async_trait::async_trait]
trait ManagedTurnPropsCapture<I, ContextState, Props>: Send {
    type Error: Error + Send + Sync + 'static;

    async fn capture(
        &mut self,
        session: &AgentSession<I, ContextState>,
    ) -> Result<Props, Self::Error>;
}

struct SyncTurnPropsCapture<BuildProps> {
    build_props: BuildProps,
}

#[async_trait::async_trait]
impl<I, ContextState, Props, BuildProps> ManagedTurnPropsCapture<I, ContextState, Props>
    for SyncTurnPropsCapture<BuildProps>
where
    I: Sync,
    ContextState: Sync,
    Props: Send,
    BuildProps: FnMut(&AgentSession<I, ContextState>) -> Props + Send,
{
    type Error = Infallible;

    async fn capture(
        &mut self,
        session: &AgentSession<I, ContextState>,
    ) -> Result<Props, Self::Error> {
        Ok((self.build_props)(session))
    }
}

struct HarnessTurnPropsCapture<'a, H, I>
where
    H: MountedTurnHarness<I>,
{
    harness: &'a H,
    source: &'a H::Source,
    call_props: &'a H::CallProps,
    call_label: &'a str,
    _transcript: PhantomData<fn(I)>,
}

#[async_trait::async_trait]
impl<H, I> ManagedTurnPropsCapture<I, H::ContextState, H::TurnProps>
    for HarnessTurnPropsCapture<'_, H, I>
where
    H: MountedTurnHarness<I>,
    I: Send + Sync + 'static,
{
    type Error = H::CaptureError;

    async fn capture(
        &mut self,
        session: &AgentSession<I, H::ContextState>,
    ) -> Result<H::TurnProps, Self::Error> {
        self.harness
            .capture_turn_props(TurnCaptureContext {
                context: session.context(),
                call_props: self.call_props,
                source: self.source,
                call_label: self.call_label,
            })
            .await
    }
}

/// Prepare one logical turn against a pinned mounted epoch, then transfer the
/// final Ready attempt into the managed provider owner.
///
/// `build_props` is application-defined and runs again after every history
/// replacement. `render_user` therefore sees props derived from the current
/// draft, while System bytes and provider capabilities always come from the
/// same `epoch`. `start_attempt` is called exactly once, after the provider has
/// accepted the final request candidate. Request history is always the canonical
/// durable-history prefix followed by the session working set, so a context
/// replacement can only persist durable transcript items.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn prepare_managed_mounted_turn<
    C,
    Props,
    I,
    ContextState,
    Executor,
    Version,
    StoreError,
    PublicationInput,
    StartError,
    BuildProps,
    RenderUser,
    StartAttempt,
>(
    runtime: &tokio::runtime::Handle,
    epoch: &MountedEpoch<C, Props>,
    provider_epoch: Arc<Executor::Epoch>,
    draft_session: AgentSession<I, ContextState>,
    call_label: impl Into<StorageString>,
    model: StorageString,
    max_tokens: u64,
    executor: Arc<Executor>,
    build_props: BuildProps,
    render_user: RenderUser,
    start_attempt: StartAttempt,
    max_context_replacements: usize,
) -> Result<
    ManagedMountedTurn<I, ContextState, Version, StoreError, Executor::Error, PublicationInput>,
    ManagedMountedTurnPrepareError<Executor::Error, StartError>,
>
where
    C: TurnChannels,
    Props: Send + 'static,
    I: Clone + Send + Sync + 'static,
    ContextState: Send + Sync + 'static,
    Executor: MountedProviderExecutor<I> + 'static,
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
    StartError: Error + Send + Sync + 'static,
    BuildProps: FnMut(&AgentSession<I, ContextState>) -> Props + Send,
    RenderUser: for<'props> FnMut(UserTurnContext<'props, Props>) -> UserView,
    StartAttempt: for<'epoch, 'props> FnOnce(
        &tokio::runtime::Handle,
        &PreparedUserTurn<'epoch, 'props, C, Props>,
    ) -> Result<
        ManagedActiveAttempt<Version, StoreError, PublicationInput>,
        StartError,
    >,
{
    let mut capture = SyncTurnPropsCapture { build_props };
    let mut provider_start_gate = None;
    let mut provider_checkpoint = None;
    prepare_managed_mounted_turn_with_capture(
        runtime,
        None,
        &mut provider_start_gate,
        &mut provider_checkpoint,
        epoch,
        provider_epoch,
        None,
        None,
        draft_session,
        call_label,
        model,
        max_tokens,
        executor,
        &mut capture,
        render_user,
        start_attempt,
        max_context_replacements,
        None,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn prepare_managed_mounted_turn_with_capture<
    C,
    Props,
    I,
    ContextState,
    Executor,
    Version,
    StoreError,
    PublicationInput,
    StartError,
    Capture,
    RenderUser,
    StartAttempt,
>(
    runtime: &Handle,
    runtime_policy: Option<MountedRuntimePolicy>,
    provider_start_gate: &mut Option<&mut dyn ManagedProviderStartGate<Version>>,
    provider_checkpoint: &mut Option<ManagedCallCheckpoint<Version>>,
    epoch: &MountedEpoch<C, Props>,
    provider_epoch: Arc<Executor::Epoch>,
    provider_cursor: Option<ProviderTurnCursor>,
    provider_operation: Option<ProviderOperationIdentity>,
    mut draft_session: AgentSession<I, ContextState>,
    call_label: impl Into<StorageString>,
    model: StorageString,
    max_tokens: u64,
    executor: Arc<Executor>,
    capture: &mut Capture,
    mut render_user: RenderUser,
    start_attempt: StartAttempt,
    max_context_replacements: usize,
    cancellation: Option<ProviderCancellationToken>,
) -> Result<
    ManagedMountedTurn<I, ContextState, Version, StoreError, Executor::Error, PublicationInput>,
    ManagedMountedTurnPrepareError<Executor::Error, StartError, Capture::Error>,
>
where
    C: TurnChannels,
    Props: Send + 'static,
    I: Clone + Send + Sync + 'static,
    ContextState: Send + Sync + 'static,
    Executor: MountedProviderExecutor<I> + 'static,
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
    StartError: Error + Send + Sync + 'static,
    Capture: ManagedTurnPropsCapture<I, ContextState, Props>,
    RenderUser: for<'props> FnMut(UserTurnContext<'props, Props>) -> UserView,
    StartAttempt: for<'epoch, 'props> FnOnce(
        &Handle,
        &PreparedUserTurn<'epoch, 'props, C, Props>,
    ) -> Result<
        ManagedActiveAttempt<Version, StoreError, PublicationInput>,
        StartError,
    >,
{
    let preparation_result = async {
        let call_label = call_label.into();
        let mounted_turn = epoch.begin_turn(call_label.clone());
        let mut replacements = 0;
        let mut start_attempt = Some(start_attempt);

        loop {
            let props = match cancellation.as_ref() {
                Some(token) => tokio::select! {
                    result = capture.capture(&draft_session) => result
                        .map_err(ManagedMountedTurnPrepareError::Capture)?,
                    reason = token.cancelled() => {
                        return Err(ManagedMountedTurnPrepareError::Cancelled { reason });
                    }
                },
                None => capture
                    .capture(&draft_session)
                    .await
                    .map_err(ManagedMountedTurnPrepareError::Capture)?,
            };
            let prepared = mounted_turn
                .prepare_user(&props, &mut render_user)
                .map_err(ManagedMountedTurnPrepareError::Component)?;
            let (resolved_user, next_user_document_cursor) = resolve_user_document(
                prepared.user_document().clone(),
                draft_session.user_document_cursor(),
            )
            .map_err(ManagedMountedTurnPrepareError::Resolution)?;
            let user = render_pom_document(&resolved_user)
                .map_err(ManagedMountedTurnPrepareError::Render)?;
            let context = draft_session.context();
            let committed_history_len = context.history().len();
            let mut history = context.history().to_vec();
            history.extend_from_slice(context.working_set());
            let mut request = MountedProviderRequest::new(
                call_label.clone(),
                history,
                user,
                model.clone(),
                max_tokens,
            )
            .with_provider_cursor(provider_cursor.clone());
            if let Some(operation) = provider_operation.as_ref() {
                request = request.with_provider_operation(operation.clone());
            }
            let budget = ContextPreparationBudget::new(
                replacements,
                max_context_replacements,
                committed_history_len,
            );

            let context_preparation = async {
                let preparation =
                    executor.prepare_context(provider_epoch.as_ref(), &request, budget);
                match runtime_policy {
                    Some(policy) => {
                        tokio::time::timeout(policy.context_preparation_timeout(), preparation)
                            .await
                            .map_err(|_| {
                                ManagedMountedTurnPrepareError::ContextPreparationTimeout {
                                    timeout: policy.context_preparation_timeout(),
                                }
                            })?
                    }
                    None => preparation.await,
                }
                .map_err(ManagedMountedTurnPrepareError::Provider)
            };
            let preparation = match cancellation.as_ref() {
                Some(token) => tokio::select! {
                    result = context_preparation => result?,
                    reason = token.cancelled() => {
                        return Err(ManagedMountedTurnPrepareError::Cancelled { reason });
                    }
                },
                None => context_preparation.await?,
            };

            match preparation {
                ContextPreparation::Ready => {
                    if let Some(token) = cancellation.as_ref() {
                        if let Some(reason) = token.reason() {
                            return Err(ManagedMountedTurnPrepareError::Cancelled { reason });
                        }
                    }
                    let attempt = start_attempt
                        .take()
                        .expect("a final Ready candidate starts exactly one attempt")(
                        runtime, &prepared,
                    )
                    .map_err(ManagedMountedTurnPrepareError::Attempt)?;
                    let attempt = if let Some(gate) = provider_start_gate.as_deref_mut() {
                        match gate.mark_provider_started().await {
                            Ok(checkpoint) => {
                                *provider_checkpoint = Some(checkpoint);
                                attempt
                            }
                            Err(source) => {
                                return match attempt.abort(BindingAbortReason::Cancelled).await {
                                    Ok(_) => Err(
                                        ManagedMountedTurnPrepareError::ProviderAdmission(source),
                                    ),
                                    Err(cleanup) => Err(
                                        ManagedMountedTurnPrepareError::ProviderAdmissionCleanup {
                                            source,
                                            cleanup,
                                        },
                                    ),
                                };
                            }
                        }
                    } else {
                        attempt
                    };
                    let execution = start_managed_provider_execution_with_grace(
                        runtime,
                        executor,
                        provider_epoch,
                        request.clone(),
                        attempt,
                        runtime_policy.map(MountedRuntimePolicy::provider_cancellation_grace),
                    );
                    if let Some(gate) = provider_start_gate.as_deref_mut() {
                        gate.provider_spawned();
                    }
                    return Ok(ManagedMountedTurn {
                        epoch_id: epoch.id(),
                        turn_instance_id: mounted_turn.id(),
                        request,
                        draft_session,
                        next_user_document_cursor,
                        execution,
                    });
                }
                ContextPreparation::ReplaceHistory { history } => {
                    if replacements >= max_context_replacements {
                        return Err(ManagedMountedTurnPrepareError::ReplacementLimit {
                            limit: max_context_replacements,
                        });
                    }
                    replacements += 1;
                    draft_session.replace_history(history);
                }
                ContextPreparation::ResyncUserDocument => {
                    if replacements >= max_context_replacements {
                        return Err(ManagedMountedTurnPrepareError::ReplacementLimit {
                            limit: max_context_replacements,
                        });
                    }
                    replacements += 1;
                    draft_session.reset_user_document_cursor();
                }
            }
        }
    }
    .await;

    match preparation_result {
        Ok(turn) => Ok(turn),
        Err(preparation) => {
            if let Some(gate) = provider_start_gate.as_deref_mut() {
                match gate.abandon_unstarted().await {
                    Ok(abandoned) => *provider_checkpoint = Some(abandoned),
                    Err(cleanup) => {
                        return Err(ManagedMountedTurnPrepareError::ReservationCleanup {
                            preparation: Box::new(preparation),
                            cleanup,
                        });
                    }
                }
            }
            Err(preparation)
        }
    }
}

/// Transfer a managed active attempt into a provider-execution task.
pub(crate) fn start_managed_provider_execution<I, Executor, Version, StoreError, PublicationInput>(
    runtime: &tokio::runtime::Handle,
    executor: Arc<Executor>,
    provider_epoch: Arc<Executor::Epoch>,
    request: MountedProviderRequest<I>,
    attempt: ManagedActiveAttempt<Version, StoreError, PublicationInput>,
) -> ManagedProviderExecution<I, Version, StoreError, Executor::Error, PublicationInput>
where
    I: Send + 'static,
    Executor: MountedProviderExecutor<I> + 'static,
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    start_managed_provider_execution_with_grace(
        runtime,
        executor,
        provider_epoch,
        request,
        attempt,
        None,
    )
}

fn start_managed_provider_execution_with_grace<I, Executor, Version, StoreError, PublicationInput>(
    runtime: &Handle,
    executor: Arc<Executor>,
    provider_epoch: Arc<Executor::Epoch>,
    request: MountedProviderRequest<I>,
    attempt: ManagedActiveAttempt<Version, StoreError, PublicationInput>,
    provider_cancellation_grace: Option<std::time::Duration>,
) -> ManagedProviderExecution<I, Version, StoreError, Executor::Error, PublicationInput>
where
    I: Send + 'static,
    Executor: MountedProviderExecutor<I> + 'static,
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    let (cancellation, cancellation_receiver) = oneshot::channel();
    let (completion, completion_receiver) = oneshot::channel();
    runtime.spawn(async move {
        let result = run_managed_provider_execution(
            executor,
            provider_epoch,
            request,
            attempt,
            cancellation_receiver,
            provider_cancellation_grace,
        )
        .await;
        if let Err(undelivered) = completion.send(result) {
            cleanup_undelivered_provider_result(undelivered).await;
        }
    });
    ManagedProviderExecution {
        cancellation: Some(cancellation),
        completion: completion_receiver,
    }
}

async fn cleanup_undelivered_provider_result<
    I,
    Version,
    StoreError,
    ProviderError,
    PublicationInput,
>(
    result: ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput>,
) where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    if let Ok(ManagedProviderExecutionOutcome::Completed(completion)) = result {
        let (_, _, finished) = completion.into_parts();
        let _ = finished.abort(BindingAbortReason::Cancelled).await;
    }
}

async fn run_managed_provider_execution<I, Executor, Version, StoreError, PublicationInput>(
    executor: Arc<Executor>,
    provider_epoch: Arc<Executor::Epoch>,
    request: MountedProviderRequest<I>,
    mut attempt: ManagedActiveAttempt<Version, StoreError, PublicationInput>,
    mut cancellation: oneshot::Receiver<ProviderCancellationReason>,
    provider_cancellation_grace: Option<std::time::Duration>,
) -> ManagedProviderResult<I, Version, StoreError, Executor::Error, PublicationInput>
where
    I: Send + 'static,
    Executor: MountedProviderExecutor<I> + 'static,
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    let cancellation_source = ProviderCancellationSource::new();
    let provider_token = cancellation_source.token();
    let (provider_result, requested_cancellation, provider_join_timed_out) = {
        let execution = executor.execute(
            provider_epoch.as_ref(),
            request,
            &mut attempt,
            provider_token,
        );
        tokio::pin!(execution);
        tokio::select! {
            biased;
            requested = &mut cancellation => {
                let reason = requested.unwrap_or(ProviderCancellationReason::OwnerCancelled);
                cancellation_source.cancel(reason);
                match provider_cancellation_grace {
                    Some(grace) => match tokio::time::timeout(grace, &mut execution).await {
                        Ok(result) => (Some(result), Some(reason), false),
                        Err(_) => (None, Some(reason), true),
                    },
                    None => (Some(execution.await), Some(reason), false),
                }
            }
            result = &mut execution => (Some(result), None, false),
        }
    };

    if let Some(reason) = requested_cancellation {
        let (cursor, provider_error) = match provider_result {
            Some(Err(source)) => (
                ProviderCancellationCursorDisposition::Indeterminate,
                Some(source),
            ),
            Some(Ok(MountedProviderExit::Cancelled {
                reason: provider_reason,
                cursor,
            })) if provider_reason == reason => (cursor, None),
            Some(Ok(MountedProviderExit::Cancelled { .. })) => {
                (ProviderCancellationCursorDisposition::Indeterminate, None)
            }
            None | Some(Ok(MountedProviderExit::Completed { .. })) => {
                (ProviderCancellationCursorDisposition::Indeterminate, None)
            }
        };
        return cancel_attempt(
            attempt,
            reason,
            cursor,
            provider_error,
            provider_join_timed_out,
        )
        .await;
    }

    match provider_result.expect("provider result is present without owner cancellation") {
        Ok(MountedProviderExit::Completed { commit, cursor }) => {
            finish_attempt(attempt, commit, cursor, cancellation).await
        }
        Ok(MountedProviderExit::Cancelled { reason, cursor }) => {
            cancel_attempt(attempt, reason, cursor, None, false).await
        }
        Err(source) => match attempt.abort(BindingAbortReason::ProviderFailure).await {
            Ok(abort) => Err(ManagedProviderExecutionError::Provider { source, abort }),
            Err(cleanup) => Err(ManagedProviderExecutionError::Cleanup {
                provider_error: Some(source),
                source: cleanup,
            }),
        },
    }
}

async fn finish_attempt<I, Version, StoreError, ProviderError, PublicationInput>(
    attempt: ManagedActiveAttempt<Version, StoreError, PublicationInput>,
    executor_commit: ExecutorCommit<I>,
    provider_cursor: Option<ProviderTurnCursor>,
    mut cancellation: oneshot::Receiver<ProviderCancellationReason>,
) -> ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput>
where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    let finish = attempt.finish();
    tokio::pin!(finish);
    tokio::select! {
        biased;
        requested = &mut cancellation => {
            let reason = requested.unwrap_or(ProviderCancellationReason::OwnerCancelled);
            let finished = finish.await.map_err(ManagedProviderExecutionError::Attempt)?;
            cancel_finished(
                finished,
                reason,
                ProviderCancellationCursorDisposition::Indeterminate,
                None,
                false,
            )
            .await
        }
        result = &mut finish => result
            .map(|finished| {
                ManagedProviderExecutionOutcome::Completed(ManagedProviderCompletion {
                    executor_commit,
                    provider_cursor,
                    finished,
                })
            })
            .map_err(ManagedProviderExecutionError::Attempt),
    }
}

async fn cancel_finished<I, Version, StoreError, ProviderError, PublicationInput>(
    finished: ManagedFinishedAttempt<Version, StoreError, PublicationInput>,
    reason: ProviderCancellationReason,
    cursor: ProviderCancellationCursorDisposition,
    provider_error: Option<ProviderError>,
    provider_join_timed_out: bool,
) -> ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput>
where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    match finished.abort(BindingAbortReason::Cancelled).await {
        Ok(abort) => Ok(ManagedProviderExecutionOutcome::Cancelled(
            ManagedProviderCancellation {
                reason,
                cursor,
                provider_error,
                provider_join_timed_out,
                abort,
            },
        )),
        Err(source) => Err(ManagedProviderExecutionError::Cleanup {
            provider_error,
            source,
        }),
    }
}

async fn cancel_attempt<I, Version, StoreError, ProviderError, PublicationInput>(
    attempt: ManagedActiveAttempt<Version, StoreError, PublicationInput>,
    reason: ProviderCancellationReason,
    cursor: ProviderCancellationCursorDisposition,
    provider_error: Option<ProviderError>,
    provider_join_timed_out: bool,
) -> ManagedProviderResult<I, Version, StoreError, ProviderError, PublicationInput>
where
    Version: Clone + Send + 'static,
    StoreError: Error + Send + Sync + 'static,
    ProviderError: Error + Send + Sync + 'static,
    PublicationInput: Send + 'static,
{
    match attempt.abort(BindingAbortReason::Cancelled).await {
        Ok(abort) => Ok(ManagedProviderExecutionOutcome::Cancelled(
            ManagedProviderCancellation {
                reason,
                cursor,
                provider_error,
                provider_join_timed_out,
                abort,
            },
        )),
        Err(source) => Err(ManagedProviderExecutionError::Cleanup {
            provider_error,
            source,
        }),
    }
}

