    #[derive(Clone)]
    struct CountingLive {
        aborts: Arc<AtomicUsize>,
    }

    #[async_trait::async_trait]
    impl LiveEffectRuntime<()> for CountingLive {
        type Error = Infallible;

        async fn apply(
            &mut self,
            _context: &LiveEffectContext,
            _effect: (),
        ) -> Result<(), Self::Error> {
            Ok(())
        }

        async fn abort(
            &mut self,
            _context: &LiveAbortContext,
        ) -> Result<LiveEffectAbortAck, Self::Error> {
            self.aborts.fetch_add(1, Ordering::SeqCst);
            Ok(LiveEffectAbortAck::NoEffectsApplied)
        }
    }

    struct StoreObservedLive {
        store: Arc<MountedStore>,
        aborts: Arc<AtomicUsize>,
        applied: bool,
    }

    #[async_trait::async_trait]
    impl LiveEffectRuntime<()> for StoreObservedLive {
        type Error = Infallible;

        async fn apply(
            &mut self,
            _context: &LiveEffectContext,
            _effect: (),
        ) -> Result<(), Self::Error> {
            self.applied = true;
            self.store.live_apply_calls.fetch_add(1, Ordering::SeqCst);
            if self.store.gate_live_apply.load(Ordering::SeqCst) {
                self.store.live_apply_entered.store(true, Ordering::SeqCst);
                self.store.live_apply_entered_notify.notify_waiters();
                self.store.live_apply_release.notified().await;
            }
            Ok(())
        }

        async fn abort(
            &mut self,
            _context: &LiveAbortContext,
        ) -> Result<LiveEffectAbortAck, Self::Error> {
            self.aborts.fetch_add(1, Ordering::SeqCst);
            Ok(if self.applied {
                LiveEffectAbortAck::CompensationCompleted
            } else {
                LiveEffectAbortAck::NoEffectsApplied
            })
        }
    }

