    fn finish_contract() -> XmlNode {
        XmlNode::new(XmlName::try_from("selection").unwrap())
    }

    fn gated_finish_system(
        context: SystemMountContext<'_, FinishProps>,
    ) -> SystemView<TestChannels> {
        let binding_aborts = Arc::clone(&context.props().binding_aborts);
        system_view(
            StreamingXml::<TurnEmission<TestChannels>, ()>::new(finish_contract())
                .state_with(|| ())
                .on_finish(|_| vec![TurnEmission::Live(())])
                .on_abort(move |_, _| {
                    binding_aborts.fetch_add(1, Ordering::SeqCst);
                    BindingAbortAck::LocalCleanupCompleted
                })
                .into_component(),
        )
    }

    fn start_gated_finish_attempt(
        live: GatedFinishLive,
    ) -> (ManagedActiveAttempt, Arc<AtomicUsize>) {
        let binding_aborts = Arc::new(AtomicUsize::new(0));
        let epoch = mount_system_epoch(
            &FinishProps {
                binding_aborts: Arc::clone(&binding_aborts),
            },
            gated_finish_system,
        )
        .unwrap();
        let turn = epoch.begin_turn("managed-provider-finish-race");
        let prepared = turn.prepare_user(&(), |_| user_view(())).unwrap();
        let attempt = super::super::managed_attempt::start_managed_streaming_attempt(
            &prepared,
            epoch.channel_type_info(),
            live,
            IgnoreUpdates,
        )
        .unwrap();
        (attempt, binding_aborts)
    }

