    fn text_xml_node(name: &str, value: &str) -> XmlNode {
        let mut node = XmlNode::new(XmlName::try_from(name).unwrap());
        node.push(MixedContent::text(TextNode::new(value)));
        node
    }

    fn text_document(name: &str, value: &str) -> Document {
        Document::from_xml(text_xml_node(name, value))
    }

    fn history_document(history: &[String]) -> Document {
        Document::build(|document| {
            document.xml_slot(DiffSlot::present(
                DiffStrategy::Recursive,
                text_xml_node("agent_context", &history.join(" | ")),
            ));
        })
    }

    fn preparation_system(
        context: SystemMountContext<'_, PreparationMountProps>,
    ) -> SystemView<TestChannels, PreparationTurnProps> {
        context
            .props()
            .system_renders
            .fetch_add(1, Ordering::SeqCst);
        let state_initializations = Arc::clone(&context.props().state_initializations);
        let binding_aborts = Arc::clone(&context.props().binding_aborts);
        system_view(component((
            text_document("stable_policy", "keep the mounted system stable"),
            StreamingXml::<TurnEmission<TestChannels>, ()>::new(finish_contract())
                .state_with(move || {
                    state_initializations.fetch_add(1, Ordering::SeqCst);
                })
                .on_abort(move |_, _| {
                    binding_aborts.fetch_add(1, Ordering::SeqCst);
                    BindingAbortAck::LocalCleanupCompleted
                })
                .into_component(),
        )))
    }

    fn preparation_user(context: UserTurnContext<'_, PreparationTurnProps>) -> UserView {
        context.props().user_renders.fetch_add(1, Ordering::SeqCst);
        user_view(history_document(&context.props().history))
    }

    fn session_with_seeded_cursor() -> AgentSession<String, usize> {
        let mut context = PromptContext::<String, usize>::without_system();
        context.push_history("old history".to_owned());
        context.push_working_set("working context".to_owned());
        *context.context_state_mut() = 7;
        let mut session = AgentSession::new(context);
        let (_, cursor) = resolve_user_document(
            history_document(&["old history".to_owned()]),
            &UserDocumentCursor::default(),
        )
        .unwrap();
        assert_eq!(cursor.len(), 1);
        session.set_user_document_cursor(cursor);
        session
    }

