    struct TestExecutor {
        mode: ExecutorMode,
        started: Arc<Notify>,
        release: Arc<Notify>,
        joined: Arc<AtomicBool>,
        executions: AtomicUsize,
        cancellation_reason: Arc<std::sync::Mutex<Option<ProviderCancellationReason>>>,
        cancelled: Notify,
        attachments: Arc<std::sync::Mutex<Vec<ObservedProviderAttachment>>>,
        durable_attach_calls: AtomicUsize,
        durable_installs: std::sync::Mutex<Vec<TestDurableProviderInstall>>,
        durable_rehydrates: AtomicUsize,
        durable_rehydrated_cursors: std::sync::Mutex<Vec<Option<ProviderTurnCursor>>>,
        durable_rehydrate_hook: std::sync::Mutex<Option<Box<dyn FnOnce() + Send>>>,
        gate_durable_attachment: AtomicBool,
        durable_attachment_entered: AtomicBool,
        durable_attachment_entered_notify: Notify,
        durable_attachment_release: Notify,
        operation_status: std::sync::Mutex<ProviderOperationStatus>,
        operation_inspections: std::sync::Mutex<Vec<ProviderOperationIdentity>>,
        preparations: Arc<std::sync::Mutex<Vec<ObservedPreparation>>>,
        tool_results: Arc<std::sync::Mutex<Vec<ProviderToolResult>>>,
    }

    impl TestExecutor {
        fn new(mode: ExecutorMode) -> Self {
            Self {
                mode,
                started: Arc::new(Notify::new()),
                release: Arc::new(Notify::new()),
                joined: Arc::new(AtomicBool::new(false)),
                executions: AtomicUsize::new(0),
                cancellation_reason: Arc::new(std::sync::Mutex::new(None)),
                cancelled: Notify::new(),
                attachments: Arc::new(std::sync::Mutex::new(Vec::new())),
                durable_attach_calls: AtomicUsize::new(0),
                durable_installs: std::sync::Mutex::new(Vec::new()),
                durable_rehydrates: AtomicUsize::new(0),
                durable_rehydrated_cursors: std::sync::Mutex::new(Vec::new()),
                durable_rehydrate_hook: std::sync::Mutex::new(None),
                gate_durable_attachment: AtomicBool::new(false),
                durable_attachment_entered: AtomicBool::new(false),
                durable_attachment_entered_notify: Notify::new(),
                durable_attachment_release: Notify::new(),
                operation_status: std::sync::Mutex::new(ProviderOperationStatus::Unknown),
                operation_inspections: std::sync::Mutex::new(Vec::new()),
                preparations: Arc::new(std::sync::Mutex::new(Vec::new())),
                tool_results: Arc::new(std::sync::Mutex::new(Vec::new())),
            }
        }

        async fn wait_until_executions(&self, expected: usize) {
            timeout(TEST_COORDINATION_TIMEOUT, async {
                loop {
                    let started = self.started.notified();
                    if self.executions.load(Ordering::SeqCst) >= expected {
                        return;
                    }
                    started.await;
                }
            })
            .await
            .expect("provider execution should start");
        }

        async fn wait_until_cancelled(&self) -> ProviderCancellationReason {
            timeout(TEST_COORDINATION_TIMEOUT, async {
                loop {
                    let cancelled = self.cancelled.notified();
                    if let Some(reason) = *self.cancellation_reason.lock().unwrap() {
                        return reason;
                    }
                    cancelled.await;
                }
            })
            .await
            .expect("provider execution should observe cancellation")
        }

        async fn wait_until_durable_attachment_entered(&self) {
            timeout(TEST_COORDINATION_TIMEOUT, async {
                loop {
                    let entered = self.durable_attachment_entered_notify.notified();
                    if self.durable_attachment_entered.load(Ordering::SeqCst) {
                        return;
                    }
                    entered.await;
                }
            })
            .await
            .expect("durable provider attachment should reach its test gate");
        }

        fn install_durable_rehydrate_hook(&self, hook: impl FnOnce() + Send + 'static) {
            *self.durable_rehydrate_hook.lock().unwrap() = Some(Box::new(hook));
        }

        fn set_operation_status(&self, status: ProviderOperationStatus) {
            *self.operation_status.lock().unwrap() = status;
        }

        fn operation_inspections(&self) -> Vec<ProviderOperationIdentity> {
            self.operation_inspections.lock().unwrap().clone()
        }

        fn durable_cursor(epoch: &TestProviderEpoch, provider_turn: usize) -> ProviderTurnCursor {
            ProviderTurnCursor::new(
                "mounted-test-provider",
                1,
                epoch
                    .durable_epoch_id
                    .as_ref()
                    .expect("cursor mode requires a durable provider epoch")
                    .clone(),
                epoch
                    .durable_artifact_fingerprint
                    .as_ref()
                    .expect("cursor mode requires a durable provider artifact")
                    .clone(),
                json!({ "provider_turn": provider_turn }),
            )
            .expect("the test provider cursor contract is valid")
        }
    }

    #[async_trait::async_trait]
    impl MountedProviderExecutor<String> for TestExecutor {
        type Error = TestProviderError;
        type Epoch = TestProviderEpoch;

        async fn prepare_context(
            &self,
            epoch: &Self::Epoch,
            request: &MountedProviderRequest<String>,
            budget: ContextPreparationBudget,
        ) -> Result<ContextPreparation<String>, Self::Error> {
            let invocation = {
                let mut preparations = self.preparations.lock().unwrap();
                let invocation = preparations.len();
                preparations.push(ObservedPreparation {
                    history: request.history().to_vec(),
                    user: request.user().to_owned(),
                    epoch_id: epoch.epoch_id,
                    provider_cursor: request.provider_cursor().cloned(),
                    can_replace: budget.can_replace(),
                    max_replacements: budget.max_replacements(),
                    committed_history_len: budget.committed_history_len(),
                });
                invocation
            };

            match self.mode {
                ExecutorMode::ReplaceThenReady if invocation == 0 => {
                    Ok(ContextPreparation::ReplaceHistory {
                        history: vec!["compacted summary".to_owned()],
                    })
                }
                ExecutorMode::ResyncUserThenReady if invocation == 0 => {
                    Ok(ContextPreparation::ResyncUserDocument)
                }
                ExecutorMode::AlwaysReplace => Ok(ContextPreparation::ReplaceHistory {
                    history: vec![format!("replacement {invocation}")],
                }),
                ExecutorMode::PreparationFailure => Err(TestProviderError::Preparation),
                ExecutorMode::PreparationHangs => std::future::pending().await,
                _ => Ok(ContextPreparation::Ready),
            }
        }

        async fn execute(
            &self,
            epoch: &Self::Epoch,
            _request: MountedProviderRequest<String>,
            wire: &mut dyn super::super::FallibleProviderWirePort,
            cancellation: super::super::ProviderCancellationToken,
        ) -> Result<MountedProviderExit<String>, Self::Error> {
            let execution = self.executions.fetch_add(1, Ordering::SeqCst);
            self.started.notify_one();
            let result = match self.mode {
                ExecutorMode::Complete => {
                    wire.submit(ProviderWireEvent::Text(TextTurnEvent::TextDelta(
                        "provider-output".to_owned(),
                    )))
                    .await
                    .map_err(|source| TestProviderError::Wire(source.to_string()))?;
                    wire.submit(ProviderWireEvent::Text(TextTurnEvent::TextComplete(
                        "provider-output".to_owned(),
                    )))
                    .await
                    .map_err(|source| TestProviderError::Wire(source.to_string()))?;
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
                ExecutorMode::CompleteWithoutWire => {
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
                ExecutorMode::CompleteWithDurableCursor => {
                    MountedProviderExit::completed_with_cursor(
                        ExecutorCommit::new(["assistant".to_owned()]),
                        Self::durable_cursor(epoch, execution + 1),
                    )
                }
                ExecutorMode::CompleteWithDurableCursorThenMissing if execution == 0 => {
                    MountedProviderExit::completed_with_cursor(
                        ExecutorCommit::new(["assistant".to_owned()]),
                        Self::durable_cursor(epoch, 1),
                    )
                }
                ExecutorMode::CompleteWithDurableCursorThenMissing => {
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
                ExecutorMode::CompleteExceptSecondWaitsForCancellation if execution == 1 => {
                    let reason = cancellation.cancelled().await;
                    *self.cancellation_reason.lock().unwrap() = Some(reason);
                    self.cancelled.notify_waiters();
                    MountedProviderExit::cancelled_without_cursor_change(reason)
                }
                ExecutorMode::CompleteExceptSecondWaitsForCancellation => {
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
                ExecutorMode::WaitThenComplete => {
                    self.release.notified().await;
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
                ExecutorMode::ReplaceThenReady | ExecutorMode::ResyncUserThenReady => {
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
                ExecutorMode::AlwaysReplace
                | ExecutorMode::PreparationFailure
                | ExecutorMode::PreparationHangs => {
                    return Err(TestProviderError::UnexpectedExecution);
                }
                ExecutorMode::WaitForCancellation => {
                    let reason = cancellation.cancelled().await;
                    *self.cancellation_reason.lock().unwrap() = Some(reason);
                    self.cancelled.notify_waiters();
                    MountedProviderExit::cancelled_without_cursor_change(reason)
                }
                ExecutorMode::WaitForCancellationWithMismatchedReason => {
                    let reason = cancellation.cancelled().await;
                    *self.cancellation_reason.lock().unwrap() = Some(reason);
                    self.cancelled.notify_waiters();
                    MountedProviderExit::cancelled_without_cursor_change(
                        ProviderCancellationReason::RuntimeShutdown,
                    )
                }
                ExecutorMode::WaitForCancellationWithDurableCursor => {
                    let reason = cancellation.cancelled().await;
                    *self.cancellation_reason.lock().unwrap() = Some(reason);
                    self.cancelled.notify_waiters();
                    MountedProviderExit::cancelled_with_resume_cursor(
                        reason,
                        Self::durable_cursor(epoch, execution + 1),
                    )
                }
                ExecutorMode::IgnoreCancellation => std::future::pending().await,
                ExecutorMode::PanicDuringExecution => {
                    panic!("scripted mounted provider task panic")
                }
                ExecutorMode::ReturnCancelled => {
                    MountedProviderExit::cancelled(ProviderCancellationReason::RuntimeShutdown)
                }
                ExecutorMode::SurfaceWireFailure => {
                    let failure = wire
                        .submit(ProviderWireEvent::Text(TextTurnEvent::TextDelta(
                            "rejected".to_owned(),
                        )))
                        .await
                        .expect_err("the interpreter should terminate the wire");
                    self.joined.store(true, Ordering::SeqCst);
                    return Err(TestProviderError::Wire(failure.to_string()));
                }
                ExecutorMode::NativeToolRoundTrip => {
                    let acknowledgement = wire
                        .submit(ProviderWireEvent::Tool(ProviderToolCall::new(
                            "native-call-1",
                            "inspect",
                            json!({ "subject": "plaza" }),
                        )))
                        .await
                        .map_err(|source| TestProviderError::Wire(source.to_string()))?;
                    let ProviderWireAck::ToolResult { result, replayed } = acknowledgement else {
                        return Err(TestProviderError::MissingWireFailure);
                    };
                    assert!(!replayed);
                    self.tool_results.lock().unwrap().push(result);
                    MountedProviderExit::completed(ExecutorCommit::new(["assistant".to_owned()]))
                }
            };
            self.joined.store(true, Ordering::SeqCst);
            Ok(result)
        }
    }

    impl MountedProviderEpochAttacher<String> for TestExecutor {
        fn attach_epoch(&self, epoch: MountedProviderEpoch) -> Result<Self::Epoch, Self::Error> {
            let epoch_id = epoch.epoch_id();
            self.attachments
                .lock()
                .unwrap()
                .push(ObservedProviderAttachment {
                    durable_epoch_id: None,
                    system: epoch.system().to_owned(),
                    epoch_id,
                    tool_names: epoch
                        .tools()
                        .iter()
                        .map(|tool| tool.name().to_owned())
                        .collect(),
                });
            Ok(TestProviderEpoch {
                epoch_id,
                durable_epoch_id: None,
                durable_artifact_fingerprint: None,
            })
        }
    }

    #[async_trait::async_trait]
    impl DurableMountedProviderExecutor<String> for TestExecutor {
        fn durable_provider_adapter_contract(&self) -> ProviderAdapterContract {
            ProviderAdapterContract::new("mounted-test-provider", 1).unwrap()
        }

        async fn attach_durable_epoch(
            &self,
            request: ProviderEpochAttachRequest<'_>,
        ) -> Result<AttachedProviderEpoch<Self::Epoch>, Self::Error> {
            self.durable_attach_calls.fetch_add(1, Ordering::SeqCst);
            let (epoch_id, receipt, installed) = {
                let mut installs = self.durable_installs.lock().unwrap();
                if let Some(existing) = installs
                    .iter()
                    .find(|install| install.durable_epoch_id == *request.durable_epoch_id())
                {
                    assert_eq!(
                        existing.receipt.artifact_fingerprint(),
                        request.fingerprint(),
                        "one durable provider epoch id cannot install two System artifacts"
                    );
                    (existing.epoch_id, existing.receipt.clone(), false)
                } else {
                    let epoch_id = HarnessEpochId::fresh();
                    self.attachments
                        .lock()
                        .unwrap()
                        .push(ObservedProviderAttachment {
                            durable_epoch_id: Some(request.durable_epoch_id().clone()),
                            system: request.system().to_owned(),
                            epoch_id,
                            tool_names: request
                                .tools()
                                .iter()
                                .map(|tool| tool.name().to_owned())
                                .collect(),
                        });
                    let receipt = ProviderEpochReceipt::new(
                        "mounted-test-provider",
                        1,
                        request.durable_epoch_id().clone(),
                        request.fingerprint().clone(),
                        json!({ "durable_epoch_id": request.durable_epoch_id().as_str() }),
                    )
                    .expect("the test provider receipt contract is valid");
                    installs.push(TestDurableProviderInstall {
                        durable_epoch_id: request.durable_epoch_id().clone(),
                        epoch_id,
                        receipt: receipt.clone(),
                    });
                    (epoch_id, receipt, true)
                }
            };
            if !installed {
                return Ok(AttachedProviderEpoch::new(
                    TestProviderEpoch {
                        epoch_id,
                        durable_epoch_id: Some(request.durable_epoch_id().clone()),
                        durable_artifact_fingerprint: Some(request.fingerprint().clone()),
                    },
                    receipt,
                ));
            }
            if self.gate_durable_attachment.load(Ordering::SeqCst) {
                self.durable_attachment_entered
                    .store(true, Ordering::SeqCst);
                self.durable_attachment_entered_notify.notify_waiters();
                self.durable_attachment_release.notified().await;
            }
            Ok(AttachedProviderEpoch::new(
                TestProviderEpoch {
                    epoch_id,
                    durable_epoch_id: Some(request.durable_epoch_id().clone()),
                    durable_artifact_fingerprint: Some(request.fingerprint().clone()),
                },
                receipt,
            ))
        }

        async fn rehydrate_durable_epoch(
            &self,
            request: ProviderEpochRehydrateRequest<'_>,
        ) -> Result<Self::Epoch, Self::Error> {
            assert_eq!(request.receipt().adapter(), "mounted-test-provider");
            assert_eq!(request.receipt().schema_version(), 1);
            self.durable_rehydrates.fetch_add(1, Ordering::SeqCst);
            self.durable_rehydrated_cursors
                .lock()
                .unwrap()
                .push(request.cursor().cloned());
            let hook = self.durable_rehydrate_hook.lock().unwrap().take();
            if let Some(hook) = hook {
                hook();
            }
            Ok(TestProviderEpoch {
                epoch_id: HarnessEpochId::fresh(),
                durable_epoch_id: Some(request.durable_epoch_id().clone()),
                durable_artifact_fingerprint: Some(request.fingerprint().clone()),
            })
        }
    }

    #[async_trait::async_trait]
    impl DurableMountedProviderOperationController<String> for TestExecutor {
        async fn inspect_operation(
            &self,
            _epoch: &Self::Epoch,
            operation: &ProviderOperationIdentity,
        ) -> Result<ProviderOperationStatus, Self::Error> {
            self.operation_inspections
                .lock()
                .unwrap()
                .push(operation.clone());
            Ok(self.operation_status.lock().unwrap().clone())
        }

        async fn cancel_operation(
            &self,
            _epoch: &Self::Epoch,
            _operation: &ProviderOperationIdentity,
            _reason: ProviderCancellationReason,
        ) -> Result<ProviderOperationStatus, Self::Error> {
            Ok(self.operation_status.lock().unwrap().clone())
        }
    }

    struct OwnerMountProps {
        policy: &'static str,
        system_renders: Arc<AtomicUsize>,
        system_component_builds: Arc<AtomicUsize>,
        runtime_seed: OwnerRuntimeSeed,
    }

    #[derive(Clone)]
    struct OwnerRuntimeSeed {
        contract_kind: &'static str,
        catalog: Arc<DurableSystem<TestChannels, OwnerTurnProps>>,
    }

    impl OwnerRuntimeSeed {
        fn prompt_only_runtime() -> Self {
            Self {
                contract_kind: "prompt-only",
                catalog: Arc::new(
                    DurableSystem::new(std::iter::empty::<
                        crate::component::DurableComponent<TestChannels, OwnerTurnProps>,
                    >())
                    .unwrap(),
                ),
            }
        }

        fn finish_live_runtime() -> Self {
            let component = crate::component::DurableComponent::binding(
                RuntimeContract::new(OWNER_FINISH_DECLARATION_ID, "v1").unwrap(),
                pom_view(Document::from_xml(finish_contract())),
                owner_finish_declaration(),
            );
            Self {
                contract_kind: "finish-live",
                catalog: Arc::new(DurableSystem::new([component]).unwrap()),
            }
        }

        fn native_inspect_runtime(calls: Arc<AtomicUsize>) -> Self {
            let dispatcher_calls = Arc::clone(&calls);
            let declaration =
                ProviderCapabilityDeclaration::new([owner_native_spec()], move || {
                    OwnerNativeDispatcher {
                        calls: Arc::clone(&dispatcher_calls),
                    }
                })
                .unwrap();
            let component = crate::component::DurableComponent::provider(
                RuntimeContract::new(OWNER_NATIVE_DECLARATION_ID, "v1").unwrap(),
                pom_view(()),
                declaration,
            );
            Self {
                contract_kind: "native-inspect",
                catalog: Arc::new(DurableSystem::new([component]).unwrap()),
            }
        }

        fn pure_native_inspect_runtime() -> Self {
            let component = crate::component::durable_provider_contract::<
                TestChannels,
                OwnerTurnProps,
            >(owner_pure_native_contract(), ());
            Self {
                contract_kind: "pure-native-inspect",
                catalog: Arc::new(DurableSystem::new([component]).unwrap()),
            }
        }

        fn finish_live_with_native_tools_runtime(calls: Arc<AtomicUsize>) -> Self {
            let finish =
                crate::component::DurableComponent::<OwnerLocalChannels, OwnerTurnProps>::binding(
                    RuntimeContract::new(OWNER_FINISH_DECLARATION_ID, "v1").unwrap(),
                    pom_view(Document::from_xml(finish_contract())),
                    owner_local_finish_declaration(),
                );
            let dispatcher_calls = Arc::clone(&calls);
            let native_tools =
                ProviderCapabilityDeclaration::<OwnerLocalChannels, OwnerTurnProps>::new(
                    [owner_native_spec(), owner_lookup_spec()],
                    move || OwnerNativeDispatcher {
                        calls: Arc::clone(&dispatcher_calls),
                    },
                )
                .unwrap();
            let native =
                crate::component::DurableComponent::<OwnerLocalChannels, OwnerTurnProps>::provider(
                    RuntimeContract::new(OWNER_NATIVE_DECLARATION_ID, "v1").unwrap(),
                    pom_view(text_document("tool_contract", "inspect-and-lookup")),
                    native_tools,
                );
            let catalog = crate::component::durable_system((
                finish,
                pom_view(text_document("post_rules", "after-streaming")),
                native,
            ))
            .map_channels(TurnChannelMap::new(|()| (), |()| (), |()| (), |()| ()));
            Self {
                contract_kind: "finish-live-native-tools",
                catalog: Arc::new(catalog),
            }
        }

        fn with_policy(
            mut self,
            policy: &'static str,
            system_renders: Arc<AtomicUsize>,
            system_component_builds: Arc<AtomicUsize>,
        ) -> Self {
            let runtime = match Arc::try_unwrap(self.catalog) {
                Ok(runtime) => runtime,
                Err(_) => panic!("a runtime seed must be completed before it is shared"),
            };
            self.catalog = Arc::new(crate::component::durable_system((
                owner_policy_pom(policy, system_renders, system_component_builds),
                runtime,
            )));
            self
        }

        fn contract_kind(&self) -> &'static str {
            self.contract_kind
        }

        fn take_create_component(&self) -> Component<TestChannels, OwnerTurnProps> {
            self.catalog.take_create_component()
        }

        fn catalog(&self) -> Arc<DurableSystem<TestChannels, OwnerTurnProps>> {
            Arc::clone(&self.catalog)
        }
    }

