    #[async_trait::async_trait]
    impl MountedTurnHarness<String> for OwnerHarness {
        type CallProps = str;
        type TurnProps = OwnerTurnProps;
        type Source = OwnerSource;
        type ContextState = usize;
        type Channels = TestChannels;
        type CaptureError = OwnerCaptureRejected;

        async fn capture_turn_props(
            &self,
            context: TurnCaptureContext<
                '_,
                String,
                Self::ContextState,
                Self::CallProps,
                Self::Source,
            >,
        ) -> Result<Self::TurnProps, Self::CaptureError> {
            self.captures.fetch_add(1, Ordering::SeqCst);
            let source_revision = context.source().revision.load(Ordering::SeqCst);
            if source_revision == usize::MAX {
                return Err(OwnerCaptureRejected);
            }
            Ok(OwnerTurnProps {
                call_label: context.call_label().to_owned(),
                call_props: context.call_props().to_owned(),
                source_revision,
                history: context.context().history().to_vec(),
                user_renders: Arc::clone(&self.user_renders),
            })
        }

        fn user(&self, context: UserTurnContext<'_, Self::TurnProps>) -> UserView {
            owner_user(context)
        }
    }

    fn owner_user(context: UserTurnContext<'_, OwnerTurnProps>) -> UserView {
        let props = context.props();
        props.user_renders.fetch_add(1, Ordering::SeqCst);
        if props.call_props == "invalid-render" {
            return user_view(Document::build(|blocks| blocks.paragraph(|_| {})));
        }
        user_view((
            text_document("call", &props.call_label),
            text_document("input", &props.call_props),
            text_document("source_revision", &props.source_revision.to_string()),
            history_document(&props.history),
        ))
    }

