    #[derive(Clone)]
    struct BlockingMountedBoundary {
        entered: Arc<AtomicBool>,
        entered_notify: Arc<Notify>,
        released: Arc<(Mutex<bool>, Condvar)>,
    }

    impl BlockingMountedBoundary {
        fn new() -> Self {
            Self {
                entered: Arc::new(AtomicBool::new(false)),
                entered_notify: Arc::new(Notify::new()),
                released: Arc::new((Mutex::new(false), Condvar::new())),
            }
        }

        fn block(&self) {
            self.entered.store(true, Ordering::SeqCst);
            self.entered_notify.notify_waiters();
            let (released, wake) = &*self.released;
            let mut released = released.lock().unwrap();
            while !*released {
                released = wake.wait(released).unwrap();
            }
        }

        async fn wait_until_entered(&self) {
            loop {
                let entered = self.entered_notify.notified();
                if self.entered.load(Ordering::SeqCst) {
                    break;
                }
                entered.await;
            }
        }

        fn release(&self) {
            let (released, wake) = &*self.released;
            *released.lock().unwrap() = true;
            wake.notify_all();
        }
    }

    struct BlockingMountedFingerprintFactory {
        boundary: BlockingMountedBoundary,
    }

    impl PublicationFingerprintFactory<MountedSessionMutation<String, usize>, String, u64>
        for BlockingMountedFingerprintFactory
    {
        type Error = MountedFingerprintError;

        fn fingerprint(
            &self,
            context: PublicationFingerprintContext<
                '_,
                MountedSessionMutation<String, usize>,
                String,
                u64,
            >,
        ) -> Result<PublicationCandidateFingerprint, Self::Error> {
            self.boundary.block();
            MountedFingerprintFactory.fingerprint(context)
        }
    }

    #[derive(Debug, Clone, thiserror::Error)]
    enum MountedStoreError {
        #[error(transparent)]
        DurableKey(#[from] crate::component::DurableKeyError),

        #[error("mounted publication expected revision {expected}, but found {actual}")]
        Revision { expected: u64, actual: u64 },

        #[error("mounted owner revision is exhausted")]
        RevisionExhausted,

        #[error("mounted publication request id collided")]
        Collision,

        #[error("mounted publication was rejected")]
        Rejected,

        #[error("mounted publication response was lost")]
        Indeterminate,

        #[error("mounted call admission lease expired before publication")]
        LeaseExpired,

        #[error("mounted session store is scoped to `{expected}`, not `{actual}`")]
        SessionScope {
            expected: DurableSessionId,
            actual: DurableSessionId,
        },

        #[error("mounted durable epoch fence is stale or does not match the artifact")]
        EpochFence,

        #[error("mounted durable epoch store transition is invalid")]
        EpochTransition,

        #[error("mounted owner snapshot has no active durable epoch artifact")]
        ActiveEpochMissing,

        #[error("mounted owner snapshot points at a different active durable epoch artifact")]
        ActiveEpochMismatch,

        #[error("mounted owner session was not initialized before active-epoch snapshot load")]
        OwnerSessionMissing,

        #[error("mounted owner session System does not match its active durable epoch")]
        OwnerSystemMismatch,

        #[error("mounted owner snapshot provider cursor does not match its active durable epoch")]
        OwnerProviderCursorMismatch,
    }

