    #[test]
    fn cancellation_with_pending_publication_requires_recovery() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let store = Arc::new(MountedStore::default());
            let executor = Arc::new(TestExecutor::new(ExecutorMode::WaitForCancellation));
            let factory = PublicOwnerFactory {
                runtime: test_mounted_runtime(),
                executor: Arc::clone(&executor),
                session_id: DurableSessionId::new("forgotten-city/cancel-pending-publication")
                    .unwrap(),
                store: Arc::clone(&store),
                start_calls: Arc::new(AtomicUsize::new(0)),
                binding_system_renders: Arc::new(AtomicUsize::new(0)),
            };
            let agent = PublicMountedAgent::open(
                &factory,
                captured_owner_definition(
                    Arc::new(AtomicUsize::new(0)),
                    Arc::new(AtomicUsize::new(0)),
                    Arc::new(AtomicUsize::new(0)),
                    Arc::new(AtomicUsize::new(0)),
                ),
            )
            .await
            .unwrap();
            let call_id = DurableCallId::new("cancel-pending-publication-call").unwrap();
            let input_id =
                DurableCallInputId::new("cancel-pending-publication-call/input-v1").unwrap();
            let mut call = agent
                .start(
                    MountedCallInput::new(
                        call_id.clone(),
                        input_id.clone(),
                        "cancel-pending-publication",
                        Arc::<str>::from("inspect plaza"),
                        Arc::new(OwnerSource {
                            revision: AtomicUsize::new(1),
                        }),
                    )
                    .unwrap(),
                )
                .await
                .unwrap();
            executor.wait_until_executions(1).await;
            {
                let mut state = store.state.lock().unwrap();
                let session_id = state.session_id.clone().unwrap();
                let running = state.call_ledger.get(&call_id).cloned().unwrap();
                let DurableCallStatus::Running { lease, .. } = running.status() else {
                    panic!("the provider-started call must retain a Running lease")
                };
                state.pending_publication = Some(ClaimedCallPublication::new(
                    session_id,
                    running.epoch_contract_id().clone(),
                    call_id.clone(),
                    input_id.clone(),
                    running.next_turn_index(),
                    lease.clone(),
                    PublicationCandidateFingerprint::new("cancel-pending-publication/v1").unwrap(),
                ));
            }

            assert_eq!(call.cancel().await, MountedCallCancellation::Requested);
            assert!(matches!(
                call.wait().await,
                Err(MountedWaitError::RecoveryRequired { .. })
            ));
            assert!(matches!(
                store
                    .state
                    .lock()
                    .unwrap()
                    .call_ledger
                    .get(&call_id)
                    .map(DurableCallState::status),
                Some(DurableCallStatus::RecoveryRequired {
                    reason: DurableCallRecoveryReason::CancellationPendingPublication,
                    ..
                })
            ));
        });

        drop(runtime);
    }

    struct CancellationSettlementFixture {
        store: MountedStore,
        session_id: DurableSessionId,
        epoch_contract_id: EpochContractId,
        active_epoch: ActiveEpochArtifact,
        call_id: DurableCallId,
        input_id: DurableCallInputId,
        request_id: PublicationRequestId,
        lease_id: DurableCallLeaseId,
        expected_revision: u64,
    }

    impl CancellationSettlementFixture {
        fn new(label: &str) -> Self {
            let session_id = DurableSessionId::new(format!("forgotten-city/{label}")).unwrap();
            let epoch_contract_id = EpochContractId::new(format!("owner/{label}/v1")).unwrap();
            let active_epoch = test_active_epoch_artifact(
                epoch_contract_id.clone(),
                &format!("{label}/epoch"),
                "<policy>cancellation-fault-matrix</policy>",
            );
            let call_id = DurableCallId::new(format!("{label}-call")).unwrap();
            let input_id = DurableCallInputId::new(format!("{label}-call/input-v1")).unwrap();
            let request_id = PublicationRequestId::new(format!("{label}-request")).unwrap();
            let lease_id = DurableCallLeaseId::new(format!("{label}-lease")).unwrap();
            let expected_revision = 41;
            let lease = DurableCallLease::new(lease_id.clone(), request_id.clone(), 2_000);
            let running = DurableCallState::running(
                call_id.clone(),
                input_id.clone(),
                epoch_contract_id.clone(),
                0,
                None,
                lease,
                DurableCallReservationOrigin::New,
            );
            let store = MountedStore::default();
            {
                let mut state = store.state.lock().unwrap();
                state.session_id = Some(session_id.clone());
                state.revision = expected_revision;
                state.epoch = MountedEpochStoreState::Active(active_epoch.clone());
                state.call_ledger.upsert(running);
            }
            Self {
                store,
                session_id,
                epoch_contract_id,
                active_epoch,
                call_id,
                input_id,
                request_id,
                lease_id,
                expected_revision,
            }
        }

        fn request(
            &self,
            disposition: MountedCallCancellationDisposition,
        ) -> MountedCallCancellationSettlementRequest<'_, u64> {
            MountedCallCancellationSettlementRequest::new(
                &self.session_id,
                &self.active_epoch,
                &self.epoch_contract_id,
                &self.call_id,
                &self.input_id,
                0,
                &self.request_id,
                &self.lease_id,
                &self.expected_revision,
                disposition,
            )
        }
    }

    fn assert_cancellation_settlement_recovery(
        outcome: MountedCallCancellationSettlement<u64>,
        expected_reason: DurableCallRecoveryReason,
    ) {
        let MountedCallCancellationSettlement::RecoveryRequired { state, .. } = outcome else {
            panic!("cancellation fault must fence the call with durable recovery")
        };
        assert!(matches!(
            state.status(),
            DurableCallStatus::RecoveryRequired { reason, .. } if *reason == expected_reason
        ));
    }

