    #[test]
    fn cancellation_settlement_rejects_foreign_lease_without_transitioning_call() {
        let fixture = CancellationSettlementFixture::new("cancel-foreign-lease");
        let foreign_lease = DurableCallLeaseId::new("cancel-foreign-lease-other").unwrap();
        let foreign_lease_outcome = fixture
            .store
            .settle_cancelled_call(MountedCallCancellationSettlementRequest::new(
                &fixture.session_id,
                &fixture.active_epoch,
                &fixture.epoch_contract_id,
                &fixture.call_id,
                &fixture.input_id,
                0,
                &fixture.request_id,
                &foreign_lease,
                &fixture.expected_revision,
                MountedCallCancellationDisposition::StopUnchanged,
            ))
            .unwrap();

        assert!(matches!(
            foreign_lease_outcome,
            MountedCallCancellationSettlement::Existing(ref state)
                if matches!(state.status(), DurableCallStatus::Running { .. })
        ));
        let foreign_request =
            PublicationRequestId::new("cancel-foreign-lease-other-request").unwrap();
        let foreign_request_outcome = fixture
            .store
            .settle_cancelled_call(MountedCallCancellationSettlementRequest::new(
                &fixture.session_id,
                &fixture.active_epoch,
                &fixture.epoch_contract_id,
                &fixture.call_id,
                &fixture.input_id,
                0,
                &foreign_request,
                &fixture.lease_id,
                &fixture.expected_revision,
                MountedCallCancellationDisposition::StopUnchanged,
            ))
            .unwrap();
        assert!(matches!(
            foreign_request_outcome,
            MountedCallCancellationSettlement::Existing(ref state)
                if matches!(state.status(), DurableCallStatus::Running { .. })
        ));
        let state = fixture.store.state.lock().unwrap();
        assert_eq!(state.revision, fixture.expected_revision);
        assert!(matches!(
            state
                .call_ledger
                .get(&fixture.call_id)
                .map(DurableCallState::status),
            Some(DurableCallStatus::Running { .. })
        ));
    }

    #[test]
    fn cancellation_recovery_settlement_is_idempotent_for_the_exact_fence() {
        let fixture = CancellationSettlementFixture::new("cancel-recovery-idempotency");
        let first = fixture
            .store
            .settle_cancelled_call(fixture.request(MountedCallCancellationDisposition::Recover(
                DurableCallRecoveryReason::CancellationIndeterminate,
            )))
            .unwrap();
        assert_cancellation_settlement_recovery(
            first,
            DurableCallRecoveryReason::CancellationIndeterminate,
        );
        let revision_after_first = fixture.store.state.lock().unwrap().revision;

        let retry = fixture
            .store
            .settle_cancelled_call(
                fixture.request(MountedCallCancellationDisposition::StopUnchanged),
            )
            .unwrap();
        assert_cancellation_settlement_recovery(
            retry,
            DurableCallRecoveryReason::CancellationIndeterminate,
        );
        let state = fixture.store.state.lock().unwrap();
        assert_eq!(state.revision, revision_after_first);
        assert!(matches!(
            state
                .call_ledger
                .get(&fixture.call_id)
                .map(DurableCallState::status),
            Some(DurableCallStatus::RecoveryRequired {
                reason: DurableCallRecoveryReason::CancellationIndeterminate,
                ..
            })
        ));
    }

