    struct PreProviderFailureObservation {
        error: BoundMountedCallError,
        store: Arc<MountedStore>,
        executor: Arc<TestExecutor>,
        call_id: DurableCallId,
        captures: Arc<AtomicUsize>,
        user_renders: Arc<AtomicUsize>,
        start_calls: Arc<AtomicUsize>,
        reload_required: bool,
    }

    async fn run_pre_provider_failure(
        label: &'static str,
        mode: ExecutorMode,
        source_revision: usize,
        call_props: &'static str,
        runtime_policy: MountedRuntimePolicy,
    ) -> PreProviderFailureObservation {
        let store = Arc::new(MountedStore::default());
        let captures = Arc::new(AtomicUsize::new(0));
        let user_renders = Arc::new(AtomicUsize::new(0));
        let start_calls = Arc::new(AtomicUsize::new(0));
        let system_renders = Arc::new(AtomicUsize::new(0));
        let executor = Arc::new(TestExecutor::new(mode));
        let session_id = DurableSessionId::new(format!("forgotten-city/{label}")).unwrap();
        let epoch_contract_id = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
        let call_id = DurableCallId::new(label).unwrap();
        let input_id = DurableCallInputId::new(format!("{label}/input-v1")).unwrap();
        let agent = BoundMountedAgent::open(
            test_mounted_runtime_with_policy(runtime_policy),
            OwnerHarness {
                captures: Arc::clone(&captures),
                user_renders: Arc::clone(&user_renders),
            },
            Arc::clone(&executor),
            "test-model",
            128,
            recovery_owner_binding(
                session_id,
                epoch_contract_id,
                Arc::clone(&store),
                Arc::clone(&start_calls),
                Arc::clone(&system_renders),
            ),
        )
        .await
        .unwrap();
        let source = OwnerSource {
            revision: AtomicUsize::new(source_revision),
        };
        let error = match agent
            .call(call_id.clone(), input_id, label, call_props)
            .execute(&source)
            .await
        {
            Ok(_) => panic!("pre-provider failure case `{label}` completed unexpectedly"),
            Err(error) => error,
        };
        let reload_required = agent.agent.reload_required.load(Ordering::Acquire);
        assert_eq!(system_renders.load(Ordering::SeqCst), 1);
        PreProviderFailureObservation {
            error,
            store,
            executor,
            call_id,
            captures,
            user_renders,
            start_calls,
            reload_required,
        }
    }

    struct NeverAcceptedControllerFixture {
        agent: BoundMountedAgent<OwnerHarness, TestExecutor, String, u64, OwnerMountedBinding>,
        store: Arc<MountedStore>,
        executor: Arc<TestExecutor>,
        session_id: DurableSessionId,
        call_id: DurableCallId,
        input_id: DurableCallInputId,
        request_id: PublicationRequestId,
        prior_request_id: Option<PublicationRequestId>,
        turn_index: u64,
        expected_revision: u64,
        captures: Arc<AtomicUsize>,
        user_renders: Arc<AtomicUsize>,
        start_calls: Arc<AtomicUsize>,
    }

    async fn open_never_accepted_controller_fixture(
        label: &str,
        origin: DurableCallReservationOrigin,
    ) -> NeverAcceptedControllerFixture {
        let store = Arc::new(MountedStore::default());
        let captures = Arc::new(AtomicUsize::new(0));
        let user_renders = Arc::new(AtomicUsize::new(0));
        let start_calls = Arc::new(AtomicUsize::new(0));
        let system_renders = Arc::new(AtomicUsize::new(0));
        let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
        let session_id = DurableSessionId::new(format!("forgotten-city/{label}")).unwrap();
        let epoch_contract_id = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
        let agent = BoundMountedAgent::open(
            test_mounted_runtime(),
            OwnerHarness {
                captures: Arc::clone(&captures),
                user_renders: Arc::clone(&user_renders),
            },
            Arc::clone(&executor),
            "test-model",
            128,
            recovery_owner_binding(
                session_id.clone(),
                epoch_contract_id.clone(),
                Arc::clone(&store),
                Arc::clone(&start_calls),
                Arc::clone(&system_renders),
            ),
        )
        .await
        .unwrap();

        let call_id = DurableCallId::new(format!("{label}-call")).unwrap();
        let input_id = DurableCallInputId::new(format!("{label}-call/input-v1")).unwrap();
        let request_id = PublicationRequestId::new(format!("{label}-request")).unwrap();
        let lease_id = DurableCallLeaseId::new(format!("{label}-lease")).unwrap();
        let turn_index = matches!(origin, DurableCallReservationOrigin::AwaitingContinuation)
            .then_some(1)
            .unwrap_or(0);
        let prior_request_id = matches!(origin, DurableCallReservationOrigin::AwaitingContinuation)
            .then(|| PublicationRequestId::new(format!("{label}-prior-request")).unwrap());
        let lease = DurableCallLease::new(lease_id, request_id.clone(), 2_000);
        let running = DurableCallState::running(
            call_id.clone(),
            input_id.clone(),
            epoch_contract_id,
            turn_index,
            prior_request_id.clone(),
            lease.clone(),
            origin,
        );
        let recovery = running.recovery_required(lease, DurableCallRecoveryReason::LeaseExpired);
        let expected_revision = 41;
        {
            let mut state = store.state.lock().unwrap();
            state.revision = expected_revision;
            state.call_ledger.upsert(recovery);
        }

        NeverAcceptedControllerFixture {
            agent,
            store,
            executor,
            session_id,
            call_id,
            input_id,
            request_id,
            prior_request_id,
            turn_index,
            expected_revision,
            captures,
            user_renders,
            start_calls,
        }
    }

    fn assert_new_reservation_was_abandoned(observation: &PreProviderFailureObservation) {
        assert!(matches!(
            observation.error,
            BoundMountedCallError::PreProvider { .. }
        ));
        assert_eq!(observation.executor.executions.load(Ordering::SeqCst), 0);
        assert!(!observation.reload_required);
        let stored = observation.store.state.lock().unwrap();
        assert_eq!(stored.revision, 2);
        assert!(stored.call_ledger.get(&observation.call_id).is_none());
        assert!(stored.call_ledger.active().is_none());
        assert!(stored.pending_publication.is_none());
    }

    type OwnerPublication<'agent> = ManagedMountedAgentPublication<
        'agent,
        'static,
        OwnerHarness,
        TestExecutor,
        String,
        u64,
        MountedStoreError,
        PublicationStagingPlan<MountedSessionMutation<String, usize>, u64>,
    >;

    async fn prepare_owner_publication<'agent>(
        agent: &'agent MountedAgent<OwnerHarness, TestExecutor, String, u64>,
        source: &OwnerSource,
        store: Arc<MountedStore>,
        live_aborts: Arc<AtomicUsize>,
        request_id: &'static str,
        flow: TurnFlow,
    ) -> OwnerPublication<'agent> {
        prepare_owner_publication_with_fingerprint(
            agent,
            source,
            store,
            live_aborts,
            MountedFingerprintFactory,
            request_id,
            flow,
        )
        .await
    }

    async fn prepare_owner_publication_with_fingerprint<'agent, FingerprintFactory>(
        agent: &'agent MountedAgent<OwnerHarness, TestExecutor, String, u64>,
        source: &OwnerSource,
        store: Arc<MountedStore>,
        live_aborts: Arc<AtomicUsize>,
        fingerprint_factory: FingerprintFactory,
        request_id: &'static str,
        flow: TurnFlow,
    ) -> OwnerPublication<'agent>
    where
        FingerprintFactory:
            PublicationFingerprintFactory<MountedSessionMutation<String, usize>, String, u64>,
    {
        let managed = agent
            .call("durable-owner", "inspect")
            .pin()
            .await
            .unwrap()
            .prepare_managed_durable(
                source,
                move |runtime, prepared, plan_factory| {
                    let finalizer = DurableStreamingPublicationFinalizer::new(
                        plan_factory,
                        MountedCommitStager,
                        fingerprint_factory,
                        store,
                    );
                    start_managed_streaming_attempt_with_durable_finalizer_on(
                        runtime,
                        prepared,
                        prepared.epoch().channel_type_info(),
                        CountingLive {
                            aborts: live_aborts,
                        },
                        IgnoreUpdates,
                        finalizer,
                    )
                },
                0,
            )
            .await
            .unwrap();
        let ManagedMountedAgentTurnOutcome::Completed(completion) =
            managed.complete().await.unwrap()
        else {
            panic!("the provider turn should finish before durable publication");
        };
        completion
            .prepare_durable_publication(
                PublicationRequestId::new(request_id).unwrap(),
                move |session, request, commit| {
                    session.push_history(format!("user:{}", request.user()));
                    session.extend_history(commit.append);
                    Ok::<_, Infallible>(flow)
                },
            )
            .unwrap()
    }

