    #[test]
    fn dropping_active_complete_future_cancels_with_grace_and_poisons_before_unlock() {
        let runtime = test_runtime();
        let mounted_runtime = test_mounted_runtime_with_policy(MountedRuntimePolicy::new(
            Duration::from_secs(1),
            Duration::from_millis(20),
        ));

        runtime.block_on(async {
            let system_renders = Arc::new(AtomicUsize::new(0));
            let live = GatedAbortLive::new();
            let live_for_attempt = live.clone();
            let executor = Arc::new(TestExecutor::new(ExecutorMode::IgnoreCancellation));
            let agent = MountedAgent::mount(
                mounted_runtime,
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                &owner_mount_props("stable-a", &system_renders),
                Arc::clone(&executor),
                "test-model",
                128,
                owner_session(),
            )
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let managed = agent
                .call("drop-active-complete", "inspect")
                .pin()
                .await
                .unwrap()
                .prepare_managed(
                    &source,
                    move |runtime, prepared| {
                        super::super::managed_attempt::start_managed_streaming_attempt_on(
                            runtime,
                            prepared,
                            prepared.epoch().channel_type_info(),
                            live_for_attempt,
                            IgnoreUpdates,
                        )
                    },
                    1,
                )
                .await
                .unwrap();
            let candidate = agent
                .try_mount_candidate(&owner_mount_props("stable-b", &system_renders))
                .unwrap();

            let mut completion = Box::pin(managed.complete());
            tokio::select! {
                _ = &mut completion => panic!("an active ignored provider cannot complete"),
                () = tokio::task::yield_now() => {}
            }
            drop(completion);
            live.wait_until_entered().await;

            let reconfigure =
                agent.reconfigure_with(candidate, |session| Ok::<_, Infallible>(session.clone()));
            tokio::pin!(reconfigure);
            assert!(timeout(Duration::from_millis(20), &mut reconfigure)
                .await
                .is_err());
            live.release.notify_waiters();
            assert_eq!(
                reconfigure.await,
                Err(MountedReconfigureError::CleanupUnacknowledged(
                    MountedAgentCleanupUnacknowledged
                ))
            );
            assert!(!executor.joined.load(Ordering::SeqCst));
            assert_eq!(live.aborts.load(Ordering::SeqCst), 1);
            assert_eq!(
                agent.call("poisoned", "continue").pin().await.err(),
                Some(MountedAgentUnavailable::CleanupUnacknowledged(
                    MountedAgentCleanupUnacknowledged,
                ))
            );
        });
        drop(runtime);
    }

