    #[test]
    fn dropping_a_queued_transition_reply_aborts_finished_before_unlock() {
        let runtime = test_runtime();
        let mounted_runtime = test_mounted_runtime();

        runtime.block_on(async {
            let system_renders = Arc::new(AtomicUsize::new(0));
            let live = GatedAbortLive::new();
            let live_for_attempt = live.clone();
            let agent = MountedAgent::mount(
                mounted_runtime,
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                &owner_mount_props("stable-a", &system_renders),
                Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire)),
                "test-model",
                128,
                owner_session(),
            )
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let mut managed = agent
                .call("queued-transition-reply", "inspect")
                .pin()
                .await
                .unwrap()
                .prepare_managed(
                    &source,
                    move |runtime, prepared| {
                        super::super::managed_attempt::start_managed_streaming_attempt_on(
                            runtime,
                            prepared,
                            prepared.epoch().channel_type_info(),
                            live_for_attempt,
                            IgnoreUpdates,
                        )
                    },
                    1,
                )
                .await
                .unwrap();
            let turn = managed
                .turn
                .take()
                .expect("the test extracts the low-level provider turn");
            let mut lease = managed
                .lease
                .take()
                .expect("the test extracts the pinned call lease");
            drop(managed);
            let outcome = turn.complete().await.unwrap();
            assert!(matches!(&outcome, ManagedMountedTurnOutcome::Completed(_)));
            let turn_guard = lease
                .turn_guard
                .take()
                .expect("the queued reply owns the exclusive turn guard");
            let reply = ManagedTurnTransitionReply::new(
                Ok(outcome),
                turn_guard,
                lease.agent.config.runtime.clone(),
                Arc::clone(&lease.agent.cleanup_poisoned),
            );
            drop(lease);
            let (sender, receiver) = oneshot::channel();
            assert!(sender.send(reply).is_ok());

            drop(receiver);
            live.wait_until_entered().await;
            let candidate = agent
                .try_mount_candidate(&owner_mount_props("stable-b", &system_renders))
                .unwrap();
            let reconfigure =
                agent.reconfigure_with(candidate, |session| Ok::<_, Infallible>(session.clone()));
            tokio::pin!(reconfigure);
            assert!(timeout(Duration::from_millis(20), &mut reconfigure)
                .await
                .is_err());
            live.release.notify_waiters();
            reconfigure.await.unwrap();
            assert_eq!(live.aborts.load(Ordering::SeqCst), 1);
        });
        drop(runtime);
    }

