    async fn wait_for_cleanup(executor: &TestExecutor, aborts: &AtomicUsize) {
        timeout(Duration::from_secs(1), async {
            while !executor.joined.load(Ordering::SeqCst) || aborts.load(Ordering::SeqCst) == 0 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("provider join and attempt cleanup should complete");
    }

    #[tokio::test]
    async fn mounted_preparation_rerenders_only_user_and_starts_only_the_ready_candidate() {
        let system_renders = Arc::new(AtomicUsize::new(0));
        let user_renders = Arc::new(AtomicUsize::new(0));
        let state_initializations = Arc::new(AtomicUsize::new(0));
        let start_calls = Arc::new(AtomicUsize::new(0));
        let binding_aborts = Arc::new(AtomicUsize::new(0));
        let live_aborts = Arc::new(AtomicUsize::new(0));
        let epoch = mount_system_epoch(
            &PreparationMountProps {
                system_renders: Arc::clone(&system_renders),
                state_initializations: Arc::clone(&state_initializations),
                binding_aborts: Arc::clone(&binding_aborts),
            },
            preparation_system,
        )
        .unwrap();
        let mounted_system = epoch.rendered_system().to_owned();
        let executor = Arc::new(TestExecutor::new(ExecutorMode::ReplaceThenReady));
        let provider_epoch = Arc::new(executor.attach_epoch(epoch.provider_epoch()).unwrap());
        let start_calls_for_attempt = Arc::clone(&start_calls);
        let live_aborts_for_attempt = Arc::clone(&live_aborts);
        let user_renders_for_props = Arc::clone(&user_renders);
        let channel_types = epoch.channel_type_info();

        let managed = prepare_managed_mounted_turn(
            &tokio::runtime::Handle::current(),
            &epoch,
            provider_epoch,
            session_with_seeded_cursor(),
            "mounted-preparation-test",
            "test-model".into(),
            128,
            Arc::clone(&executor),
            move |session| PreparationTurnProps {
                history: session.context().history().to_vec(),
                user_renders: Arc::clone(&user_renders_for_props),
            },
            preparation_user,
            move |runtime, prepared| {
                start_calls_for_attempt.fetch_add(1, Ordering::SeqCst);
                super::super::managed_attempt::start_managed_streaming_attempt_on(
                    runtime,
                    prepared,
                    channel_types,
                    CountingLive {
                        aborts: Arc::clone(&live_aborts_for_attempt),
                    },
                    IgnoreUpdates,
                )
            },
            1,
        )
        .await
        .unwrap();

        assert_eq!(system_renders.load(Ordering::SeqCst), 1);
        assert_eq!(user_renders.load(Ordering::SeqCst), 2);
        assert_eq!(state_initializations.load(Ordering::SeqCst), 1);
        assert_eq!(start_calls.load(Ordering::SeqCst), 1);
        assert_eq!(managed.epoch_id(), epoch.id());
        assert_eq!(
            managed.request().history(),
            ["compacted summary", "working context"]
        );
        assert!(managed.request().user().contains("compacted summary"));
        assert_eq!(
            managed.draft_session().context().history(),
            ["compacted summary"]
        );
        assert_eq!(*managed.draft_session().context().context_state(), 7);
        assert_eq!(
            managed.draft_session().context().working_set(),
            ["working context"]
        );
        assert!(managed.draft_session().user_document_cursor().is_empty());
        assert_eq!(managed.next_user_document_cursor().len(), 1);

        let preparations = executor.preparations.lock().unwrap().clone();
        assert_eq!(preparations.len(), 2);
        assert_eq!(preparations[0].history, ["old history", "working context"]);
        assert_eq!(
            preparations[1].history,
            ["compacted summary", "working context"]
        );
        assert!(!preparations[0].user.contains("compacted summary"));
        assert!(preparations[1].user.contains("compacted summary"));
        assert_eq!(preparations[0].epoch_id, epoch.id());
        assert_eq!(preparations[1].epoch_id, epoch.id());
        assert!(preparations[0].can_replace);
        assert!(!preparations[1].can_replace);
        assert_eq!(preparations[0].max_replacements, 1);
        assert_eq!(preparations[1].max_replacements, 1);
        assert_eq!(preparations[0].committed_history_len, 1);
        assert_eq!(preparations[1].committed_history_len, 1);
        drop(preparations);

        let attachments = executor.attachments.lock().unwrap().clone();
        assert_eq!(attachments.len(), 1);
        assert_eq!(attachments[0].system, mounted_system);
        assert_eq!(attachments[0].epoch_id, epoch.id());
        assert_eq!(attachments[0].tool_names, Vec::<String>::new());

        let turn_instance_id = managed.turn_instance_id();
        let ManagedMountedTurnOutcome::Completed(completion) = managed.complete().await.unwrap()
        else {
            panic!("the Ready provider should complete the mounted turn");
        };
        assert_eq!(completion.epoch_id(), epoch.id());
        assert_eq!(completion.turn_instance_id(), turn_instance_id);
        assert_eq!(
            completion.request().history(),
            ["compacted summary", "working context"]
        );
        assert_eq!(
            completion.draft_session().context().history(),
            ["compacted summary"]
        );
        assert_eq!(completion.next_user_document_cursor().len(), 1);
        assert_eq!(
            completion.provider().executor_commit().append,
            ["assistant"]
        );
        let (_, _, _, _, _, provider) = completion.into_parts();
        let (_, _, finished) = provider.into_parts();
        finished.abort(BindingAbortReason::Cancelled).await.unwrap();
        assert_eq!(binding_aborts.load(Ordering::SeqCst), 1);
        assert_eq!(live_aborts.load(Ordering::SeqCst), 1);
    }

