    #[tokio::test]
    async fn replacement_limit_exits_before_creating_an_attempt() {
        let system_renders = Arc::new(AtomicUsize::new(0));
        let user_renders = Arc::new(AtomicUsize::new(0));
        let state_initializations = Arc::new(AtomicUsize::new(0));
        let start_calls = Arc::new(AtomicUsize::new(0));
        let binding_aborts = Arc::new(AtomicUsize::new(0));
        let epoch = mount_system_epoch(
            &PreparationMountProps {
                system_renders: Arc::clone(&system_renders),
                state_initializations: Arc::clone(&state_initializations),
                binding_aborts: Arc::clone(&binding_aborts),
            },
            preparation_system,
        )
        .unwrap();
        let executor = Arc::new(TestExecutor::new(ExecutorMode::AlwaysReplace));
        let provider_epoch = Arc::new(executor.attach_epoch(epoch.provider_epoch()).unwrap());
        let user_renders_for_props = Arc::clone(&user_renders);
        let start_calls_for_attempt = Arc::clone(&start_calls);

        let result = prepare_managed_mounted_turn(
            &tokio::runtime::Handle::current(),
            &epoch,
            provider_epoch,
            session_with_seeded_cursor(),
            "mounted-preparation-limit",
            "test-model".into(),
            128,
            Arc::clone(&executor),
            move |session| PreparationTurnProps {
                history: session.context().history().to_vec(),
                user_renders: Arc::clone(&user_renders_for_props),
            },
            preparation_user,
            move |_, _| -> Result<ManagedActiveAttempt<(), Infallible>, Infallible> {
                start_calls_for_attempt.fetch_add(1, Ordering::SeqCst);
                unreachable!("a rejected preparation candidate cannot start an attempt")
            },
            1,
        )
        .await;

        let Err(ManagedMountedTurnPrepareError::ReplacementLimit { limit }) = result else {
            panic!("the second replacement should exceed the configured limit");
        };
        assert_eq!(limit, 1);
        assert_eq!(system_renders.load(Ordering::SeqCst), 1);
        assert_eq!(user_renders.load(Ordering::SeqCst), 2);
        assert_eq!(state_initializations.load(Ordering::SeqCst), 0);
        assert_eq!(start_calls.load(Ordering::SeqCst), 0);
        assert_eq!(binding_aborts.load(Ordering::SeqCst), 0);
        assert!(!executor.joined.load(Ordering::SeqCst));
        assert_eq!(executor.preparations.lock().unwrap().len(), 2);
    }

