    #[tokio::test]
    async fn explicit_cancellation_joins_provider_before_returning_abort_ack() {
        let aborts = Arc::new(AtomicUsize::new(0));
        let attempt = start_attempt(IgnoreUpdates, Arc::clone(&aborts));
        let executor = Arc::new(TestExecutor::new(ExecutorMode::WaitForCancellation));
        let execution = start_managed_provider_execution(
            &tokio::runtime::Handle::current(),
            Arc::clone(&executor),
            test_provider_epoch(&executor),
            request(),
            attempt,
        );
        executor.started.notified().await;

        let ManagedProviderExecutionOutcome::Cancelled(cancelled) = execution
            .cancel(ProviderCancellationReason::DeadlineExceeded)
            .await
            .unwrap()
        else {
            panic!("explicit cancellation should not produce a completion");
        };
        assert_eq!(
            cancelled.reason(),
            ProviderCancellationReason::DeadlineExceeded
        );
        assert_eq!(
            cancelled.cursor_disposition(),
            &ProviderCancellationCursorDisposition::Unchanged
        );
        assert!(cancelled.provider_error().is_none());
        assert!(matches!(cancelled.abort(), ManagedAttemptAbort::Aborted(_)));
        assert_eq!(
            *executor.cancellation_reason.lock().unwrap(),
            Some(ProviderCancellationReason::DeadlineExceeded)
        );
        assert!(executor.joined.load(Ordering::SeqCst));
        assert_eq!(aborts.load(Ordering::SeqCst), 1);
    }

    #[tokio::test]
    async fn mismatched_provider_cancellation_reason_is_indeterminate() {
        let aborts = Arc::new(AtomicUsize::new(0));
        let attempt = start_attempt(IgnoreUpdates, Arc::clone(&aborts));
        let executor = Arc::new(TestExecutor::new(
            ExecutorMode::WaitForCancellationWithMismatchedReason,
        ));
        let execution = start_managed_provider_execution(
            &tokio::runtime::Handle::current(),
            Arc::clone(&executor),
            test_provider_epoch(&executor),
            request(),
            attempt,
        );
        executor.started.notified().await;

        let ManagedProviderExecutionOutcome::Cancelled(cancelled) = execution
            .cancel(ProviderCancellationReason::DeadlineExceeded)
            .await
            .unwrap()
        else {
            panic!("explicit cancellation should not produce a completion");
        };
        assert_eq!(
            cancelled.reason(),
            ProviderCancellationReason::DeadlineExceeded,
            "the owner retains the reason it requested"
        );
        assert_eq!(
            cancelled.cursor_disposition(),
            &ProviderCancellationCursorDisposition::Indeterminate,
            "a mismatched provider reason cannot authorize cursor reuse"
        );
        assert_eq!(
            *executor.cancellation_reason.lock().unwrap(),
            Some(ProviderCancellationReason::DeadlineExceeded)
        );
        assert!(executor.joined.load(Ordering::SeqCst));
        assert!(matches!(cancelled.abort(), ManagedAttemptAbort::Aborted(_)));
        assert_eq!(aborts.load(Ordering::SeqCst), 1);
    }

