    #[test]
    fn dropped_reconfiguration_start_observer_still_persists_rebase_rejection() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let system_renders = Arc::new(AtomicUsize::new(0));
            let store = Arc::new(MountedStore::default());
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let contract_b = EpochContractId::new("owner/stable-b/prompt-only/v1").unwrap();
            let agent = Arc::new(
                BoundMountedAgent::open(
                    test_mounted_runtime(),
                    OwnerHarness {
                        captures: Arc::new(AtomicUsize::new(0)),
                        user_renders: Arc::new(AtomicUsize::new(0)),
                    },
                    Arc::clone(&executor),
                    "test-model",
                    128,
                    reconfigured_owner_binding(
                        DurableSessionId::new("forgotten-city/owned-reconfigure-rejected-drop")
                            .unwrap(),
                        EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap(),
                        Arc::clone(&store),
                        Arc::new(AtomicUsize::new(0)),
                        Arc::clone(&system_renders),
                        "stable-a",
                    ),
                )
                .await
                .unwrap(),
            );
            let reconfiguration_id = EpochReconfigurationId::new(
                "forgotten-city/owned-reconfigure-rejected-drop/policy-b",
            )
            .unwrap();
            let boundary = BlockingMountedBoundary::new();
            let task_boundary = boundary.clone();
            let mut start = Box::pin(agent.spawn_reconfigure_durable_with(
                reconfiguration_id.clone(),
                reconfigured_epoch_definition(
                    contract_b.clone(),
                    Arc::clone(&system_renders),
                    "stable-b",
                ),
                move |_| {
                    task_boundary.block();
                    Err::<AgentSession<String, usize>, _>(std::io::Error::other(
                        "rebase rejected after observer drop",
                    ))
                },
            ));

            tokio::select! {
                _ = start.as_mut() => {
                    panic!("start must wait for a durable rejection record")
                }
                () = boundary.wait_until_entered() => {}
            }
            let preflight = agent
                .reconfiguration_status(&reconfiguration_id)
                .await
                .unwrap();
            assert_eq!(
                preflight.operation(),
                &BoundMountedReconfigurationOperationStatus::NotDurablyAdmitted
            );
            assert_eq!(
                preflight.owner(),
                &BoundMountedOwnerEpochStatus::TransitionInProgress
            );

            drop(start);
            boundary.release();

            let settled = timeout(TEST_COORDINATION_TIMEOUT, async {
                loop {
                    let status = agent
                        .reconfiguration_status(&reconfiguration_id)
                        .await
                        .unwrap();
                    if matches!(
                        status.operation(),
                        BoundMountedReconfigurationOperationStatus::Rejected { .. }
                    ) && status.owner() == &BoundMountedOwnerEpochStatus::Current
                    {
                        break status;
                    }
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("the detached actor must persist its rejection terminal");
            assert!(matches!(
                settled.operation(),
                BoundMountedReconfigurationOperationStatus::Rejected {
                    reason: MountedEpochReconfigurationRejectionReason::HistoryRebase,
                    candidate_epoch_contract_id,
                } if candidate_epoch_contract_id == &contract_b
            ));
            assert_eq!(settled.owner(), &BoundMountedOwnerEpochStatus::Current);
            assert_eq!(system_renders.load(Ordering::SeqCst), 1);
            assert_eq!(executor.durable_attach_calls.load(Ordering::SeqCst), 1);
            assert_eq!(
                store.state.lock().unwrap().rejected_reconfigurations.len(),
                1
            );
        });
        drop(runtime);
    }

