    #[test]
    fn rejection_tombstone_is_idempotent_and_conflicts_with_every_other_id_owner() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let system_renders = Arc::new(AtomicUsize::new(0));
            let store = Arc::new(MountedStore::default());
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let session_id =
                DurableSessionId::new("forgotten-city/reconfiguration-rejection-store").unwrap();
            let contract_a = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let contract_b = EpochContractId::new("owner/stable-b/prompt-only/v1").unwrap();
            let contract_c = EpochContractId::new("owner/stable-c/prompt-only/v1").unwrap();
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                reconfigured_owner_binding(
                    session_id.clone(),
                    contract_a,
                    Arc::clone(&store),
                    Arc::new(AtomicUsize::new(0)),
                    Arc::clone(&system_renders),
                    "stable-a",
                ),
            )
            .await
            .unwrap();

            let candidate =
                reconfigured_epoch_definition(contract_b, Arc::clone(&system_renders), "stable-b");
            let candidate_projection = candidate.durable_system().runtime_projection().unwrap();
            let durable_provider = MountedDurableProvider::new(Arc::clone(&executor));
            let manifest = EpochContractManifest::from_runtime_plans(
                candidate.epoch_contract_id().clone(),
                OWNER_HOST_CONFIGURATION_FINGERPRINT,
                OWNER_RUNTIME_IMPLEMENTATION_FINGERPRINT,
                std::num::NonZeroUsize::MIN,
                durable_provider.adapter_contract(),
                candidate_projection.binding_factories(),
                candidate_projection.provider_capabilities(),
            )
            .unwrap();
            let other_candidate =
                reconfigured_epoch_definition(contract_c, Arc::clone(&system_renders), "stable-c");
            let other_projection = other_candidate
                .durable_system()
                .runtime_projection()
                .unwrap();
            let other_manifest = EpochContractManifest::from_runtime_plans(
                other_candidate.epoch_contract_id().clone(),
                OWNER_HOST_CONFIGURATION_FINGERPRINT,
                OWNER_RUNTIME_IMPLEMENTATION_FINGERPRINT,
                std::num::NonZeroUsize::MIN,
                durable_provider.adapter_contract(),
                other_projection.binding_factories(),
                other_projection.provider_capabilities(),
            )
            .unwrap();
            let (active_epoch, session, revision) = {
                let state = store.state.lock().unwrap();
                let MountedEpochStoreState::Active(active_epoch) = &state.epoch else {
                    panic!("the initial epoch must be active");
                };
                (
                    active_epoch.clone(),
                    state.initial_session.clone().unwrap(),
                    state.revision,
                )
            };
            let candidate_epoch_id =
                DurableEpochId::new("forgotten-city/reconfiguration-rejection-store/candidate")
                    .unwrap();
            let candidate_rendered = RenderedEpochArtifact::new(
                candidate_epoch_id.clone(),
                manifest.clone(),
                "<policy>stable-b</policy>".to_owned(),
            )
            .unwrap();
            let adapter = candidate_rendered.manifest().provider_adapter();
            let candidate_receipt = super::super::durable_epoch::ProviderEpochReceipt::new(
                adapter.adapter(),
                adapter.receipt_schema_version(),
                candidate_epoch_id.clone(),
                candidate_rendered.fingerprint().clone(),
                serde_json::json!({"test": "rejection-collision"}),
            )
            .unwrap();
            let candidate_active =
                ActiveEpochArtifact::new(candidate_rendered, candidate_receipt).unwrap();
            let rejection_id = EpochReconfigurationId::new(
                "forgotten-city/reconfiguration-rejection-store/rejected",
            )
            .unwrap();
            let stale_base_id = EpochReconfigurationId::new(
                "forgotten-city/reconfiguration-rejection-store/stale-base",
            )
            .unwrap();
            let reason = MountedEpochReconfigurationRejectionReason::HistoryRebase;

            let wrong_session =
                DurableSessionId::new("forgotten-city/reconfiguration-rejection-store/wrong")
                    .unwrap();
            assert!(matches!(
                store
                    .reject_epoch_reconfiguration(MountedEpochReconfigurationRejectRequest::new(
                        &wrong_session,
                        &rejection_id,
                        &active_epoch,
                        &manifest,
                        reason,
                    ))
                    .await,
                Err(MountedStoreError::SessionScope { .. })
            ));
            assert_eq!(
                store
                    .reject_epoch_reconfiguration(MountedEpochReconfigurationRejectRequest::new(
                        &session_id,
                        &stale_base_id,
                        &candidate_active,
                        &manifest,
                        reason,
                    ))
                    .await
                    .unwrap(),
                MountedEpochReconfigurationRejectOutcome::Conflict
            );
            assert_eq!(
                store
                    .reject_epoch_reconfiguration(MountedEpochReconfigurationRejectRequest::new(
                        &session_id,
                        &rejection_id,
                        &active_epoch,
                        &manifest,
                        reason,
                    ))
                    .await
                    .unwrap(),
                MountedEpochReconfigurationRejectOutcome::Recorded
            );
            assert_eq!(
                store
                    .reject_epoch_reconfiguration(MountedEpochReconfigurationRejectRequest::new(
                        &session_id,
                        &rejection_id,
                        &active_epoch,
                        &manifest,
                        reason,
                    ))
                    .await
                    .unwrap(),
                MountedEpochReconfigurationRejectOutcome::AlreadyRejected
            );
            assert_eq!(
                store
                    .reject_epoch_reconfiguration(MountedEpochReconfigurationRejectRequest::new(
                        &session_id,
                        &rejection_id,
                        &active_epoch,
                        &other_manifest,
                        reason,
                    ))
                    .await
                    .unwrap(),
                MountedEpochReconfigurationRejectOutcome::Conflict
            );
            assert_eq!(
                store
                    .reject_epoch_reconfiguration(MountedEpochReconfigurationRejectRequest::new(
                        &session_id,
                        &rejection_id,
                        &candidate_active,
                        &manifest,
                        reason,
                    ))
                    .await
                    .unwrap(),
                MountedEpochReconfigurationRejectOutcome::Conflict
            );

            let in_flight_id = EpochReconfigurationId::new(
                "forgotten-city/reconfiguration-rejection-store/in-flight",
            )
            .unwrap();
            let activated_id = EpochReconfigurationId::new(
                "forgotten-city/reconfiguration-rejection-store/activated",
            )
            .unwrap();
            let aborted_id = EpochReconfigurationId::new(
                "forgotten-city/reconfiguration-rejection-store/aborted",
            )
            .unwrap();
            let blocked_by_lane_id = EpochReconfigurationId::new(
                "forgotten-city/reconfiguration-rejection-store/blocked-by-lane",
            )
            .unwrap();
            {
                let mut state = store.state.lock().unwrap();
                let in_flight_fence = store.issue_epoch_fence(
                    &mut state,
                    DurableEpochId::new(
                        "forgotten-city/reconfiguration-rejection-store/in-flight-epoch",
                    )
                    .unwrap(),
                );
                let activated_fence =
                    store.issue_epoch_fence(&mut state, candidate_epoch_id.clone());
                let aborted_fence = store.issue_epoch_fence(
                    &mut state,
                    DurableEpochId::new(
                        "forgotten-city/reconfiguration-rejection-store/aborted-epoch",
                    )
                    .unwrap(),
                );
                state.reconfiguration = Some(MountedEpochReconfigurationState::RenderStarted {
                    id: in_flight_id.clone(),
                    base: active_epoch.clone(),
                    manifest: manifest.clone(),
                    rebased_session: session,
                    fence: in_flight_fence,
                    staged_revision: revision,
                });
                state
                    .completed_reconfigurations
                    .push(CompletedEpochReconfiguration {
                        id: activated_id.clone(),
                        base: active_epoch.clone(),
                        fence: activated_fence,
                        artifact: candidate_active,
                    });
                state
                    .aborted_reconfigurations
                    .push(AbortedEpochReconfiguration {
                        id: aborted_id.clone(),
                        base: active_epoch.clone(),
                        manifest: manifest.clone(),
                        fence: aborted_fence,
                        post_abort_revision: revision,
                    });
            }

            for owned_id in [
                &in_flight_id,
                &activated_id,
                &aborted_id,
                &blocked_by_lane_id,
            ] {
                assert_eq!(
                    store
                        .reject_epoch_reconfiguration(
                            MountedEpochReconfigurationRejectRequest::new(
                                &session_id,
                                owned_id,
                                &active_epoch,
                                &manifest,
                                reason,
                            ),
                        )
                        .await
                        .unwrap(),
                    MountedEpochReconfigurationRejectOutcome::Conflict
                );
            }
            let state = store.state.lock().unwrap();
            assert_eq!(state.revision, revision);
            assert_eq!(state.rejected_reconfigurations.len(), 1);
            assert!(matches!(state.epoch, MountedEpochStoreState::Active(_)));
            drop(state);
            drop(agent);
        });
        drop(runtime);
    }

