    #[test]
    fn mount_owned_provider_start_origin_mismatch_blocks_execution_and_fences_owner() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let system_renders = Arc::new(AtomicUsize::new(0));
            let start_calls = Arc::new(AtomicUsize::new(0));
            let store = Arc::new(MountedStore::default());
            store
                .return_mismatched_provider_start_origin
                .store(true, Ordering::SeqCst);
            let session_id =
                DurableSessionId::new("forgotten-city/provider-origin-mismatch").unwrap();
            let epoch_contract_id = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let call_id = DurableCallId::new("provider-origin-mismatch-call").unwrap();
            let input_id =
                DurableCallInputId::new("provider-origin-mismatch-call/input-v1").unwrap();
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                recovery_owner_binding(
                    session_id,
                    epoch_contract_id,
                    Arc::clone(&store),
                    Arc::clone(&start_calls),
                    system_renders,
                ),
            )
            .await
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };

            let error = match agent
                .call(
                    call_id.clone(),
                    input_id,
                    "provider-origin-mismatch",
                    "inspect",
                )
                .execute(&source)
                .await
            {
                Ok(_) => panic!("a changed reservation origin must reject provider admission"),
                Err(error) => error,
            };

            assert!(matches!(
                error,
                BoundMountedCallError::Phase {
                    phase: "preparation",
                    ..
                }
            ));
            assert_eq!(start_calls.load(Ordering::SeqCst), 1);
            assert_eq!(executor.executions.load(Ordering::SeqCst), 0);
            assert!(agent.agent.reload_required.load(Ordering::Acquire));

            let successor = agent
                .call(
                    DurableCallId::new("provider-origin-mismatch-successor").unwrap(),
                    DurableCallInputId::new("provider-origin-mismatch-successor/input-v1").unwrap(),
                    "provider-origin-mismatch-successor",
                    "inspect",
                )
                .execute(&source)
                .await;
            assert!(matches!(
                successor,
                Err(BoundMountedCallError::Unavailable(
                    MountedAgentUnavailable::ReloadRequired(_)
                ))
            ));
            assert_eq!(start_calls.load(Ordering::SeqCst), 1);
            assert_eq!(executor.executions.load(Ordering::SeqCst), 0);

            let stored = store.state.lock().unwrap();
            assert_eq!(stored.revision, 2);
            assert!(matches!(
                stored
                    .call_ledger
                    .get(&call_id)
                    .map(DurableCallState::status),
                Some(DurableCallStatus::Running {
                    origin: Some(DurableCallReservationOrigin::New),
                    ..
                })
            ));
            assert!(stored.pending_publication.is_none());
        });
        drop(runtime);
    }

