    #[test]
    fn dropped_pre_provider_caller_abandons_its_reservation_for_a_new_owner() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let system_renders = Arc::new(AtomicUsize::new(0));
            let captures = Arc::new(AtomicUsize::new(0));
            let user_renders = Arc::new(AtomicUsize::new(0));
            let start_calls = Arc::new(AtomicUsize::new(0));
            let store = Arc::new(MountedStore::default());
            let session_id = DurableSessionId::new("forgotten-city/dropped-reservation").unwrap();
            let epoch_contract_id = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let call_id = DurableCallId::new("dropped-reservation-call").unwrap();
            let input_id = DurableCallInputId::new("dropped-reservation-call/input-v1").unwrap();
            let waiting_executor = Arc::new(TestExecutor::new(ExecutorMode::PreparationHangs));
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::clone(&captures),
                    user_renders: Arc::clone(&user_renders),
                },
                Arc::clone(&waiting_executor),
                "test-model",
                128,
                recovery_owner_binding(
                    session_id.clone(),
                    epoch_contract_id.clone(),
                    Arc::clone(&store),
                    Arc::clone(&start_calls),
                    Arc::clone(&system_renders),
                ),
            )
            .await
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let mut execution = Box::pin(
                agent
                    .call(
                        call_id.clone(),
                        input_id.clone(),
                        "dropped-reservation",
                        "inspect",
                    )
                    .execute(&source),
            );

            let preparation_started = timeout(TEST_COORDINATION_TIMEOUT, async {
                while waiting_executor.preparations.lock().unwrap().is_empty() {
                    tokio::task::yield_now().await;
                }
            });
            tokio::pin!(preparation_started);
            tokio::select! {
                _ = execution.as_mut() => {
                    panic!("context preparation must remain pending until the test releases it")
                }
                result = &mut preparation_started => {
                    result.expect("the caller should reserve and enter context preparation")
                }
            }
            assert!(matches!(
                store
                    .state
                    .lock()
                    .unwrap()
                    .call_ledger
                    .get(&call_id)
                    .map(DurableCallState::status),
                Some(DurableCallStatus::Reserved { .. })
            ));
            drop(execution);

            timeout(Duration::from_secs(1), async {
                loop {
                    if store
                        .state
                        .lock()
                        .unwrap()
                        .call_ledger
                        .get(&call_id)
                        .is_none()
                    {
                        break;
                    }
                    tokio::task::yield_now().await;
                }
            })
            .await
            .expect("dropping before provider start must abandon the reservation");
            assert_eq!(waiting_executor.executions.load(Ordering::SeqCst), 0);
            assert_eq!(store.state.lock().unwrap().revision, 2);
            assert!(agent.agent.reload_required.load(Ordering::Acquire));

            let replacement_executor =
                Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let replacement = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                Arc::clone(&replacement_executor),
                "test-model",
                128,
                recovery_owner_binding(
                    session_id,
                    epoch_contract_id,
                    Arc::clone(&store),
                    Arc::new(AtomicUsize::new(0)),
                    Arc::clone(&system_renders),
                ),
            )
            .await
            .unwrap();
            let report = replacement
                .call(call_id, input_id, "replacement-owner", "inspect")
                .execute(&source)
                .await
                .expect("a new owner should run after the reservation cleanup");
            assert!(matches!(&report, BoundMountedCallOutcome::Executed { .. }));
            assert_eq!(replacement_executor.executions.load(Ordering::SeqCst), 1);
        });
        drop(runtime);
    }

    #[test]
    fn expired_reserved_call_is_rolled_back_without_recovery() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let store = Arc::new(MountedStore::default());
            let session_id = DurableSessionId::new("forgotten-city/expired-reservation").unwrap();
            let epoch_contract_id = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let call_id = DurableCallId::new("expired-reservation-call").unwrap();
            let input_id = DurableCallInputId::new("expired-reservation-call/input-v1").unwrap();
            let request_id = PublicationRequestId::new(
                "forgotten-city/expired-reservation/expired-reservation-call/turn-0",
            )
            .unwrap();
            let lease = DurableCallLease::new(
                DurableCallLeaseId::new("expired-reservation-lease").unwrap(),
                request_id,
                1_000,
            );
            {
                let mut state = store.state.lock().unwrap();
                state.session_id = Some(session_id.clone());
                state.revision = 4;
                state.call_ledger.upsert(DurableCallState::reserved(
                    call_id.clone(),
                    input_id.clone(),
                    epoch_contract_id.clone(),
                    0,
                    None,
                    lease,
                    DurableCallReservationOrigin::New,
                ));
            }

            let system_renders = Arc::new(AtomicUsize::new(0));
            let captures = Arc::new(AtomicUsize::new(0));
            let user_renders = Arc::new(AtomicUsize::new(0));
            let start_calls = Arc::new(AtomicUsize::new(0));
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::clone(&captures),
                    user_renders: Arc::clone(&user_renders),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                recovery_owner_binding(
                    session_id,
                    epoch_contract_id,
                    Arc::clone(&store),
                    Arc::clone(&start_calls),
                    Arc::clone(&system_renders),
                ),
            )
            .await
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };

            let first = match agent
                .call(
                    call_id.clone(),
                    input_id.clone(),
                    "expired-reservation",
                    "inspect",
                )
                .execute(&source)
                .await
            {
                Ok(_) => panic!("an owner with a stale snapshot must reload after rollback"),
                Err(error) => error,
            };
            assert!(matches!(
                first,
                BoundMountedCallError::Unavailable(MountedAgentUnavailable::ReloadRequired(_))
            ));
            assert_eq!(executor.executions.load(Ordering::SeqCst), 0);
            assert_eq!(captures.load(Ordering::SeqCst), 0);
            assert_eq!(user_renders.load(Ordering::SeqCst), 0);
            {
                let state = store.state.lock().unwrap();
                assert_eq!(state.revision, 5);
                assert!(state.call_ledger.get(&call_id).is_none());
            }

            agent.reload().await.unwrap();
            let report = agent
                .call(call_id.clone(), input_id, "expired-reservation", "inspect")
                .execute(&source)
                .await
                .expect("the rolled-back reservation must be claimable after reload");
            assert!(matches!(&report, BoundMountedCallOutcome::Executed { .. }));
            assert_eq!(executor.executions.load(Ordering::SeqCst), 1);
            assert_eq!(start_calls.load(Ordering::SeqCst), 1);
            assert_eq!(captures.load(Ordering::SeqCst), 1);
            assert_eq!(user_renders.load(Ordering::SeqCst), 1);
            assert_eq!(*report.receipts()[0].session_revision(), 8);
            assert!(matches!(
                store
                    .state
                    .lock()
                    .unwrap()
                    .call_ledger
                    .get(&call_id)
                    .map(DurableCallState::status),
                Some(DurableCallStatus::Settled)
            ));
        });
        drop(runtime);
    }

    #[test]
    fn pre_provider_failure_restores_the_continuation_checkpoint() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let store = Arc::new(MountedStore::default());
            let session_id = DurableSessionId::new("forgotten-city/continuation-rollback").unwrap();
            let epoch_contract_id = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let call_id = DurableCallId::new("continuation-rollback-call").unwrap();
            let input_id = DurableCallInputId::new("continuation-rollback-call/input-v1").unwrap();
            let prior_request_id = PublicationRequestId::new(
                "forgotten-city/continuation-rollback/continuation-rollback-call/turn-0",
            )
            .unwrap();
            {
                let mut stored = store.state.lock().unwrap();
                stored.session_id = Some(session_id.clone());
                stored.revision = 7;
                stored
                    .call_ledger
                    .upsert(DurableCallState::awaiting_continuation(
                        call_id.clone(),
                        input_id.clone(),
                        epoch_contract_id.clone(),
                        1,
                        prior_request_id.clone(),
                    ));
            }
            let captures = Arc::new(AtomicUsize::new(0));
            let user_renders = Arc::new(AtomicUsize::new(0));
            let start_calls = Arc::new(AtomicUsize::new(0));
            let system_renders = Arc::new(AtomicUsize::new(0));
            let executor = Arc::new(TestExecutor::new(ExecutorMode::PreparationFailure));
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::clone(&captures),
                    user_renders: Arc::clone(&user_renders),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                recovery_owner_binding(
                    session_id,
                    epoch_contract_id,
                    Arc::clone(&store),
                    Arc::clone(&start_calls),
                    Arc::clone(&system_renders),
                ),
            )
            .await
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };

            let error = match agent
                .call(
                    call_id.clone(),
                    input_id,
                    "continuation-rollback",
                    "inspect",
                )
                .execute(&source)
                .await
            {
                Ok(_) => panic!("failed continuation preparation cannot reach the provider"),
                Err(error) => error,
            };
            assert!(matches!(error, BoundMountedCallError::PreProvider { .. }));
            assert_eq!(captures.load(Ordering::SeqCst), 1);
            assert_eq!(user_renders.load(Ordering::SeqCst), 1);
            assert_eq!(start_calls.load(Ordering::SeqCst), 0);
            assert_eq!(executor.executions.load(Ordering::SeqCst), 0);
            assert!(!agent.agent.reload_required.load(Ordering::Acquire));
            {
                let stored = store.state.lock().unwrap();
                assert_eq!(stored.revision, 9);
                let restored = stored.call_ledger.get(&call_id).unwrap();
                assert!(matches!(
                    restored.status(),
                    DurableCallStatus::AwaitingContinuation
                ));
                assert_eq!(restored.next_turn_index(), 1);
                assert_eq!(restored.last_request_id(), Some(&prior_request_id));
            }
            let authoritative = agent.agent.state.read().await;
            assert_eq!(authoritative.session_revision, 9);
            let restored = authoritative.durable_call_ledger.get(&call_id).unwrap();
            assert!(matches!(
                restored.status(),
                DurableCallStatus::AwaitingContinuation
            ));
            assert_eq!(restored.last_request_id(), Some(&prior_request_id));
        });
        drop(runtime);
    }

    #[test]
    fn recovery_controller_inspects_the_exact_operation_and_restores_a_new_call() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let fixture = open_never_accepted_controller_fixture(
                "never-accepted-controller-new",
                DurableCallReservationOrigin::New,
            )
            .await;
            fixture
                .executor
                .set_operation_status(ProviderOperationStatus::NeverAccepted);
            let durable_epoch_id = {
                let state = fixture.store.state.lock().unwrap();
                let MountedEpochStoreState::Active(active_epoch) = &state.epoch else {
                    panic!("the recovery fixture must retain its active durable epoch")
                };
                active_epoch
                    .rendered()
                    .durable_epoch_id()
                    .as_str()
                    .to_owned()
            };

            let outcome = fixture
                .agent
                .reconcile_never_accepted_operation(&fixture.call_id)
                .await
                .unwrap();
            assert_eq!(
                outcome,
                BoundMountedNeverAcceptedRecovery::Restored { state: None }
            );
            let inspections = fixture.executor.operation_inspections();
            assert_eq!(inspections.len(), 1);
            let operation = &inspections[0];
            assert_eq!(operation.session_id(), fixture.session_id.as_str());
            assert_eq!(operation.durable_epoch_id(), durable_epoch_id);
            assert_eq!(operation.call_id(), fixture.call_id.as_str());
            assert_eq!(operation.input_id(), fixture.input_id.as_str());
            assert_eq!(operation.turn_index(), fixture.turn_index);
            assert_eq!(
                operation.publication_request_id(),
                fixture.request_id.as_str()
            );

            {
                let state = fixture.store.state.lock().unwrap();
                assert_eq!(state.revision, fixture.expected_revision + 2);
                assert!(state.call_ledger.get(&fixture.call_id).is_none());
            }
            let local = fixture.agent.agent.state.read().await;
            assert_eq!(local.session_revision, fixture.expected_revision + 2);
            assert!(local.durable_call_ledger.get(&fixture.call_id).is_none());
            drop(local);
            assert_eq!(fixture.executor.executions.load(Ordering::SeqCst), 0);
            assert!(fixture.executor.preparations.lock().unwrap().is_empty());
            assert!(fixture.executor.tool_results.lock().unwrap().is_empty());
            assert_eq!(fixture.captures.load(Ordering::SeqCst), 0);
            assert_eq!(fixture.user_renders.load(Ordering::SeqCst), 0);
            assert_eq!(fixture.start_calls.load(Ordering::SeqCst), 0);
        });
        drop(runtime);
    }

    #[test]
    fn recovery_controller_restores_the_continuation_checkpoint_after_never_accepted() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let fixture = open_never_accepted_controller_fixture(
                "never-accepted-controller-continuation",
                DurableCallReservationOrigin::AwaitingContinuation,
            )
            .await;
            let prior_request_id = fixture
                .prior_request_id
                .as_ref()
                .expect("a continuation fixture retains its prior checkpoint")
                .clone();
            fixture
                .executor
                .set_operation_status(ProviderOperationStatus::NeverAccepted);

            let outcome = fixture
                .agent
                .reconcile_never_accepted_operation(&fixture.call_id)
                .await
                .unwrap();
            let BoundMountedNeverAcceptedRecovery::Restored {
                state: Some(restored),
            } = outcome
            else {
                panic!("a proven unaccepted continuation must restore its checkpoint")
            };
            assert!(matches!(
                restored.status(),
                DurableCallStatus::AwaitingContinuation
            ));
            assert_eq!(restored.next_turn_index(), fixture.turn_index);
            assert_eq!(restored.last_request_id(), Some(&prior_request_id));
            let inspections = fixture.executor.operation_inspections();
            assert_eq!(inspections.len(), 1);
            assert_eq!(inspections[0].turn_index(), fixture.turn_index);
            assert_eq!(
                inspections[0].publication_request_id(),
                fixture.request_id.as_str()
            );

            let state = fixture.store.state.lock().unwrap();
            assert_eq!(state.revision, fixture.expected_revision + 2);
            let restored = state
                .call_ledger
                .get(&fixture.call_id)
                .expect("the continuation checkpoint remains durable");
            assert!(matches!(
                restored.status(),
                DurableCallStatus::AwaitingContinuation
            ));
            assert_eq!(restored.last_request_id(), Some(&prior_request_id));
            drop(state);
            assert_eq!(fixture.executor.executions.load(Ordering::SeqCst), 0);
            assert!(fixture.executor.preparations.lock().unwrap().is_empty());
            assert_eq!(fixture.captures.load(Ordering::SeqCst), 0);
            assert_eq!(fixture.user_renders.load(Ordering::SeqCst), 0);
            assert_eq!(fixture.start_calls.load(Ordering::SeqCst), 0);
        });
        drop(runtime);
    }

    #[test]
    fn recovery_controller_releases_non_never_accepted_status_without_replay() {
        let runtime = test_runtime();

        runtime.block_on(async {
            for (label, status) in [
                (
                    "running-controller-operation",
                    ProviderOperationStatus::Running,
                ),
                (
                    "completed-controller-operation",
                    ProviderOperationStatus::Completed,
                ),
                (
                    "cancelled-controller-operation",
                    ProviderOperationStatus::Cancelled {
                        cursor: ProviderCancellationCursorDisposition::Unchanged,
                    },
                ),
                (
                    "unknown-controller-operation",
                    ProviderOperationStatus::Unknown,
                ),
            ] {
                let fixture = open_never_accepted_controller_fixture(
                    label,
                    DurableCallReservationOrigin::New,
                )
                .await;
                fixture.executor.set_operation_status(status.clone());

                let outcome = fixture
                    .agent
                    .reconcile_never_accepted_operation(&fixture.call_id)
                    .await
                    .unwrap();
                assert_eq!(
                    outcome,
                    BoundMountedNeverAcceptedRecovery::ProviderStatus(status)
                );
                assert_eq!(fixture.executor.operation_inspections().len(), 1);
                let state = fixture.store.state.lock().unwrap();
                assert_eq!(state.revision, fixture.expected_revision + 2);
                let retained = state
                    .call_ledger
                    .get(&fixture.call_id)
                    .expect("a non-NeverAccepted operation must remain recovery-required");
                assert!(matches!(
                    retained.status(),
                    DurableCallStatus::RecoveryRequired { .. }
                ));
                assert!(retained.reconciliation_fence().is_none());
                drop(state);
                assert!(!fixture.agent.agent.reload_required.load(Ordering::Acquire));
                assert_eq!(fixture.executor.executions.load(Ordering::SeqCst), 0);
                assert!(fixture.executor.preparations.lock().unwrap().is_empty());
                assert!(fixture.executor.tool_results.lock().unwrap().is_empty());
                assert_eq!(fixture.captures.load(Ordering::SeqCst), 0);
                assert_eq!(fixture.user_renders.load(Ordering::SeqCst), 0);
                assert_eq!(fixture.start_calls.load(Ordering::SeqCst), 0);
            }
        });
        drop(runtime);
    }

    #[test]
    fn captured_public_definition_executes_replays_and_reopens_without_remounting_system() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let session_id =
                DurableSessionId::new("forgotten-city/public-captured-lifecycle").unwrap();
            let store = Arc::new(MountedStore::default());
            let system_renders = Arc::new(AtomicUsize::new(0));
            let system_component_builds = Arc::new(AtomicUsize::new(0));
            let captures = Arc::new(AtomicUsize::new(0));
            let user_renders = Arc::new(AtomicUsize::new(0));
            let start_calls = Arc::new(AtomicUsize::new(0));
            let binding_system_renders = Arc::new(AtomicUsize::new(0));
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let factory = PublicOwnerFactory {
                runtime: test_mounted_runtime(),
                executor: Arc::clone(&executor),
                session_id: session_id.clone(),
                store: Arc::clone(&store),
                start_calls: Arc::clone(&start_calls),
                binding_system_renders: Arc::clone(&binding_system_renders),
            };

            let agent = PublicMountedAgent::open(
                &factory,
                captured_owner_definition(
                    Arc::clone(&captures),
                    Arc::clone(&user_renders),
                    Arc::clone(&system_renders),
                    Arc::clone(&system_component_builds),
                ),
            )
            .await
            .unwrap();
            let source = Arc::new(OwnerSource {
                revision: AtomicUsize::new(1),
            });
            let first_call_id = DurableCallId::new("public-captured-call-1").unwrap();
            let first_input_id =
                DurableCallInputId::new("public-captured-call-1/input-v1").unwrap();
            let second_call_id = DurableCallId::new("public-captured-call-2").unwrap();
            let second_input_id =
                DurableCallInputId::new("public-captured-call-2/input-v1").unwrap();

            let mut first = agent
                .start(
                    MountedCallInput::new(
                        first_call_id.clone(),
                        first_input_id.clone(),
                        "public-first",
                        Arc::<str>::from("inspect plaza"),
                        Arc::clone(&source),
                    )
                    .unwrap(),
                )
                .await
                .unwrap();
            assert!(matches!(
                first.wait().await.unwrap(),
                MountedCallOutcome::Executed { .. }
            ));

            let mut second = agent
                .start(
                    MountedCallInput::new(
                        second_call_id.clone(),
                        second_input_id.clone(),
                        "public-second",
                        Arc::<str>::from("inspect forum"),
                        Arc::clone(&source),
                    )
                    .unwrap(),
                )
                .await
                .unwrap();
            assert!(matches!(
                second.wait().await.unwrap(),
                MountedCallOutcome::Executed { .. }
            ));

            let mut duplicate = agent
                .start(
                    MountedCallInput::new(
                        first_call_id.clone(),
                        first_input_id.clone(),
                        "public-first-replay",
                        Arc::<str>::from("ignored replay props"),
                        Arc::clone(&source),
                    )
                    .unwrap(),
                )
                .await
                .unwrap();
            assert!(duplicate.wait().await.unwrap().is_replayed());

            let mismatch = agent
                .start(
                    MountedCallInput::new(
                        first_call_id.clone(),
                        DurableCallInputId::new("public-captured-call-1/input-v2").unwrap(),
                        "public-first-mismatch",
                        Arc::<str>::from("changed input"),
                        Arc::clone(&source),
                    )
                    .unwrap(),
                )
                .await
                .unwrap_err();
            assert!(matches!(
                mismatch,
                MountedStartError::CallInputMismatch {
                    call_id,
                    expected,
                    actual,
                } if call_id == first_call_id
                    && expected == first_input_id
                    && actual.as_str() == "public-captured-call-1/input-v2"
            ));
            agent.reload().await.unwrap();

            assert_eq!(system_renders.load(Ordering::SeqCst), 1);
            assert_eq!(system_component_builds.load(Ordering::SeqCst), 1);
            assert_eq!(binding_system_renders.load(Ordering::SeqCst), 0);
            assert_eq!(captures.load(Ordering::SeqCst), 2);
            assert_eq!(user_renders.load(Ordering::SeqCst), 2);
            assert_eq!(start_calls.load(Ordering::SeqCst), 2);
            assert_eq!(executor.executions.load(Ordering::SeqCst), 2);
            assert_eq!(executor.attachments.lock().unwrap().len(), 1);
            drop(agent);

            let reopen_captures = Arc::new(AtomicUsize::new(0));
            let reopen_user_renders = Arc::new(AtomicUsize::new(0));
            let reopen_start_calls = Arc::new(AtomicUsize::new(0));
            let reopen_executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let reopen_factory = PublicOwnerFactory {
                runtime: test_mounted_runtime(),
                executor: Arc::clone(&reopen_executor),
                session_id,
                store: Arc::clone(&store),
                start_calls: Arc::clone(&reopen_start_calls),
                binding_system_renders: Arc::clone(&binding_system_renders),
            };
            let reopened = PublicMountedAgent::open(
                &reopen_factory,
                captured_owner_definition(
                    Arc::clone(&reopen_captures),
                    Arc::clone(&reopen_user_renders),
                    Arc::clone(&system_renders),
                    Arc::clone(&system_component_builds),
                ),
            )
            .await
            .unwrap();
            reopened.reload().await.unwrap();
            let mut replay_after_reopen = reopened
                .start(
                    MountedCallInput::new(
                        second_call_id,
                        second_input_id,
                        "public-second-reopen-replay",
                        Arc::<str>::from("ignored reopened props"),
                        source,
                    )
                    .unwrap(),
                )
                .await
                .unwrap();
            assert!(replay_after_reopen.wait().await.unwrap().is_replayed());

            assert_eq!(system_renders.load(Ordering::SeqCst), 1);
            assert_eq!(system_component_builds.load(Ordering::SeqCst), 1);
            assert_eq!(binding_system_renders.load(Ordering::SeqCst), 0);
            assert_eq!(reopen_captures.load(Ordering::SeqCst), 0);
            assert_eq!(reopen_user_renders.load(Ordering::SeqCst), 0);
            assert_eq!(reopen_start_calls.load(Ordering::SeqCst), 0);
            assert_eq!(reopen_executor.executions.load(Ordering::SeqCst), 0);
            assert!(reopen_executor.attachments.lock().unwrap().is_empty());
            assert_eq!(reopen_executor.durable_rehydrates.load(Ordering::SeqCst), 1);
        });
        drop(runtime);
    }

    #[test]
