    #[test]
    fn expired_running_lease_is_fenced_at_publication_and_requires_recovery() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let store = Arc::new(MountedStore::with_behavior(
                MountedStoreBehavior::GatedCommit,
            ));
            let system_renders = Arc::new(AtomicUsize::new(0));
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                OwnerMountedBinding {
                    session_id: DurableSessionId::new("forgotten-city/expired-publish-session")
                        .unwrap(),
                    epoch_contract_id: EpochContractId::new("owner/stable-a/prompt-only/v1")
                        .unwrap(),
                    store: Arc::clone(&store),
                    live_aborts: Arc::new(AtomicUsize::new(0)),
                    start_calls: Arc::new(AtomicUsize::new(0)),
                    flows: vec![TurnFlow::Wait],
                    expect_tool_record: false,
                    loaded_session: owner_session(),
                    loaded_session_id: Arc::new(Mutex::new(None)),
                    loaded_epoch_contract_id: Arc::new(Mutex::new(None)),
                    load_gate: None,
                    runtime_seed: owner_prompt_seed(&system_renders),
                },
            )
            .await
            .unwrap();
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let call_id = DurableCallId::new("expired-publish-call").unwrap();
            let mut execution = Box::pin(
                agent
                    .call(
                        call_id.clone(),
                        DurableCallInputId::new("expired-publish-call/input-v1").unwrap(),
                        "expired",
                        "inspect",
                    )
                    .execute(&source),
            );
            tokio::select! {
                _ = execution.as_mut() => {
                    panic!("the gated publication must prevent call completion")
                }
                () = store.wait_until_publish_entered() => {}
            }
            let expires_at = {
                let stored = store.state.lock().unwrap();
                let running = stored.call_ledger.get(&call_id).unwrap();
                let DurableCallStatus::Running { lease, .. } = running.status() else {
                    panic!("publication must retain the claimed Running lease");
                };
                lease.expires_at_unix_ms()
            };
            store.now_unix_ms.store(expires_at, Ordering::SeqCst);
            store.publish_release.notify_one();

            let error = match execution.await {
                Ok(_) => panic!("an expired owner cannot publish its completed provider turn"),
                Err(error) => error,
            };
            assert!(matches!(
                error,
                BoundMountedCallError::Unavailable(MountedAgentUnavailable::ReloadRequired(_))
            ));
            assert_eq!(executor.executions.load(Ordering::SeqCst), 1);
            let stored = store.state.lock().unwrap();
            assert!(stored.mutation.is_none());
            assert!(stored.receipts.is_empty());
            assert_eq!(stored.revision, 3);
            assert!(matches!(
                stored.call_ledger.get(&call_id).unwrap().status(),
                DurableCallStatus::RecoveryRequired { .. }
            ));
        });
        drop(runtime);
    }

