    #[test]
    fn durable_reconfigure_stages_session_and_replaces_one_system_epoch() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let store = Arc::new(MountedStore::default());
            let system_renders = Arc::new(AtomicUsize::new(0));
            let initial_start_calls = Arc::new(AtomicUsize::new(0));
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let session_id = DurableSessionId::new("forgotten-city/reconfigure").unwrap();
            let initial_contract = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let replacement_contract =
                EpochContractId::new("owner/stable-b/prompt-only/v2").unwrap();
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                reconfigured_owner_binding(
                    session_id.clone(),
                    initial_contract,
                    Arc::clone(&store),
                    Arc::clone(&initial_start_calls),
                    Arc::clone(&system_renders),
                    "stable-a",
                ),
            )
            .await
            .unwrap();

            agent
                .reconfigure_durable_with(
                    EpochReconfigurationId::new("forgotten-city/reconfigure/policy-b").unwrap(),
                    reconfigured_epoch_definition(
                        replacement_contract.clone(),
                        Arc::clone(&system_renders),
                        "stable-b",
                    ),
                    |session| {
                        let mut rebased = session.clone();
                        rebased.replace_history(vec!["compacted for policy-b".to_owned()]);
                        Ok::<_, Infallible>(rebased)
                    },
                )
                .await
                .unwrap();

            assert_eq!(system_renders.load(Ordering::SeqCst), 2);
            let attachments = executor.attachments.lock().unwrap().clone();
            assert_eq!(attachments.len(), 2);
            assert_eq!(attachments[0].system, "<policy>stable-a</policy>");
            assert_eq!(attachments[1].system, "<policy>stable-b</policy>");
            drop(attachments);
            assert_eq!(executor.durable_rehydrates.load(Ordering::SeqCst), 0);
            assert_eq!(initial_start_calls.load(Ordering::SeqCst), 0);
            {
                let configuration = agent.configuration.lock().await;
                assert_eq!(
                    configuration.epoch_definition.epoch_contract_id(),
                    &replacement_contract
                );
                assert_eq!(
                    configuration
                        .active_epoch
                        .rendered()
                        .manifest()
                        .epoch_contract_id(),
                    &replacement_contract
                );
            }
            {
                let state = agent.agent.state.read().await;
                assert_eq!(state.generation, 1);
                assert_eq!(
                    state.session.context().system(),
                    Some("<policy>stable-b</policy>")
                );
                assert_eq!(
                    state.session.context().history(),
                    ["compacted for policy-b"]
                );
                assert_eq!(state.session_revision, 2);
            }
            {
                let stored = store.state.lock().unwrap();
                assert!(stored.reconfiguration.is_none());
                assert_eq!(stored.revision, 2);
                let MountedEpochStoreState::Active(artifact) = &stored.epoch else {
                    panic!("reconfiguration must atomically activate the candidate epoch");
                };
                assert_eq!(
                    artifact.rendered().manifest().epoch_contract_id(),
                    &replacement_contract
                );
                assert_eq!(
                    stored
                        .reconfigured_session
                        .as_ref()
                        .and_then(|session| session.context().system()),
                    Some("<policy>stable-b</policy>")
                );
            }

            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let outcome = agent
                .call(
                    DurableCallId::new("reconfigure-next").unwrap(),
                    DurableCallInputId::new("reconfigure-next/input-v1").unwrap(),
                    "after-reconfigure",
                    "inspect",
                )
                .execute(&source)
                .await
                .unwrap();
            assert!(matches!(outcome, BoundMountedCallOutcome::Executed { .. }));
            assert_eq!(initial_start_calls.load(Ordering::SeqCst), 1);
        });
        drop(runtime);
    }

    #[test]
    fn durable_reconfigure_resumes_attachment_without_rerendering_system_pom() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let store = Arc::new(MountedStore::default());
            let system_renders = Arc::new(AtomicUsize::new(0));
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let session_id =
                DurableSessionId::new("forgotten-city/reconfigure-attachment").unwrap();
            let initial_contract = EpochContractId::new("owner/stable-a/prompt-only/v1").unwrap();
            let replacement_contract =
                EpochContractId::new("owner/stable-b/prompt-only/v2").unwrap();
            let agent = BoundMountedAgent::open(
                test_mounted_runtime(),
                OwnerHarness {
                    captures: Arc::new(AtomicUsize::new(0)),
                    user_renders: Arc::new(AtomicUsize::new(0)),
                },
                Arc::clone(&executor),
                "test-model",
                128,
                reconfigured_owner_binding(
                    session_id.clone(),
                    initial_contract,
                    Arc::clone(&store),
                    Arc::new(AtomicUsize::new(0)),
                    Arc::clone(&system_renders),
                    "stable-a",
                ),
            )
            .await
            .unwrap();
            let reconfiguration_id =
                EpochReconfigurationId::new("forgotten-city/reconfigure-attachment/policy-b")
                    .unwrap();
            store
                .fail_reconfigure_activation
                .store(true, Ordering::SeqCst);

            let first = agent
                .reconfigure_durable_with(
                    reconfiguration_id.clone(),
                    reconfigured_epoch_definition(
                        replacement_contract.clone(),
                        Arc::clone(&system_renders),
                        "stable-b",
                    ),
                    |session| {
                        let mut rebased = session.clone();
                        rebased.replace_history(vec!["first staged rebase".to_owned()]);
                        Ok::<_, Infallible>(rebased)
                    },
                )
                .await;
            assert!(matches!(
                first,
                Err(BoundMountedAgentReconfigureError::Phase {
                    phase: "durable epoch reconfiguration",
                    ..
                })
            ));
            assert_eq!(system_renders.load(Ordering::SeqCst), 2);
            assert_eq!(executor.attachments.lock().unwrap().len(), 2);
            let rendered_fence = {
                let stored = store.state.lock().unwrap();
                let Some(MountedEpochReconfigurationState::Rendered { id, fence, .. }) =
                    stored.reconfiguration.as_ref()
                else {
                    panic!("failed activation must retain the rendered replacement");
                };
                assert_eq!(id, &reconfiguration_id);
                let MountedEpochStoreState::Active(artifact) = &stored.epoch else {
                    panic!("failed activation must leave the prior epoch active");
                };
                assert_eq!(
                    artifact.rendered().manifest().epoch_contract_id().as_str(),
                    "owner/stable-a/prompt-only/v1"
                );
                fence.clone()
            };

            let live_recovery = agent
                .recover_abandoned_reconfiguration(
                    reconfiguration_id.clone(),
                    rendered_fence.clone(),
                )
                .await;
            assert!(matches!(
                live_recovery,
                Err(BoundMountedAgentEpochRecoveryError::InFlight { .. })
            ));

            store
                .fail_reconfigure_activation
                .store(false, Ordering::SeqCst);
            store.now_unix_ms.store(3_000, Ordering::SeqCst);
            let expired_recovery = agent
                .recover_abandoned_reconfiguration(reconfiguration_id.clone(), rendered_fence)
                .await;
            assert!(matches!(
                expired_recovery,
                Err(BoundMountedAgentEpochRecoveryError::ResumeAttachment { .. })
            ));
            {
                let stored = store.state.lock().unwrap();
                assert!(matches!(
                    stored.reconfiguration,
                    Some(MountedEpochReconfigurationState::Rendered { .. })
                ));
                assert!(stored.aborted_reconfigurations.is_empty());
            }
            assert!(agent.agent.reload_required.load(Ordering::Acquire));
            agent.reload().await.unwrap();
            agent
                .reconfigure_durable_with(
                    reconfiguration_id,
                    reconfigured_epoch_definition(
                        replacement_contract.clone(),
                        Arc::clone(&system_renders),
                        "stable-b",
                    ),
                    |session| {
                        let mut rebased = session.clone();
                        rebased.replace_history(vec![
                            "must not replace first staged rebase".to_owned()
                        ]);
                        Ok::<_, Infallible>(rebased)
                    },
                )
                .await
                .unwrap();

            // The second provider attachment RPC is an idempotent ensure for
            // the same durable epoch. The fake remote returns the original
            // binding/receipt and does not install or transport System again.
            assert_eq!(system_renders.load(Ordering::SeqCst), 2);
            assert_eq!(executor.durable_attach_calls.load(Ordering::SeqCst), 3);
            let attachments = executor.attachments.lock().unwrap().clone();
            assert_eq!(attachments.len(), 2);
            let replacement_attachment = attachments
                .iter()
                .find(|attachment| attachment.system == "<policy>stable-b</policy>")
                .expect("the provider installs replacement System exactly once")
                .clone();
            drop(attachments);
            assert_eq!(executor.durable_installs.lock().unwrap().len(), 2);
            assert_eq!(executor.durable_rehydrates.load(Ordering::SeqCst), 0);
            let state = agent.agent.state.read().await;
            assert_eq!(
                state.session.context().system(),
                Some("<policy>stable-b</policy>")
            );
            assert_eq!(state.session.context().history(), ["first staged rebase"]);
            assert_eq!(state.session_revision, 2);
            assert_eq!(
                state.provider_epoch.epoch_id,
                replacement_attachment.epoch_id
            );
            drop(state);
            let stored = store.state.lock().unwrap();
            assert!(stored.reconfiguration.is_none());
            assert_eq!(stored.revision, 2);
            let MountedEpochStoreState::Active(artifact) = &stored.epoch else {
                panic!("attachment recovery must activate the staged epoch");
            };
            assert_eq!(
                artifact.rendered().manifest().epoch_contract_id(),
                &replacement_contract
            );
            assert_eq!(
                Some(artifact.rendered().durable_epoch_id()),
                replacement_attachment.durable_epoch_id.as_ref()
            );
        });
        drop(runtime);
    }

