    #[test]
    fn revision_conflict_requires_atomic_reload_before_another_call() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let agent = test_owner_agent(test_mounted_runtime(), executor);
            let store = Arc::new(MountedStore::with_revisions(9, vec![17]));
            let live_aborts = Arc::new(AtomicUsize::new(0));
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let publication = prepare_owner_publication(
                &agent,
                &source,
                Arc::clone(&store),
                Arc::clone(&live_aborts),
                "mounted/revision-conflict",
                TurnFlow::Wait,
            )
            .await;

            let failure = match publication.publish().await {
                Ok(_) => panic!("a stale expected revision cannot publish"),
                Err(failure) => failure,
            };
            assert!(failure.is_revision_conflict());
            assert!(failure.cleanup_acknowledged());
            assert_eq!(live_aborts.load(Ordering::SeqCst), 1);
            assert!(agent.reload_required.load(Ordering::Acquire));
            assert_eq!(
                agent.call("stale", "inspect").pin().await.err(),
                Some(MountedAgentUnavailable::ReloadRequired(
                    MountedAgentReloadRequired,
                ))
            );

            let candidate = agent
                .try_mount_candidate(&owner_mount_props(
                    "stable-a",
                    &Arc::new(AtomicUsize::new(0)),
                ))
                .unwrap();
            assert!(matches!(
                agent
                    .reconfigure_with(candidate, |session| Ok::<_, Infallible>(session.clone()))
                    .await,
                Err(MountedReconfigureError::ReloadRequired(
                    MountedAgentReloadRequired
                ))
            ));

            agent.reload_durable(owner_session(), 9).await.unwrap();
            assert!(!agent.reload_required.load(Ordering::Acquire));
            let fresh = agent.call("reloaded", "inspect").pin().await.unwrap();
            assert_eq!(*fresh.session_revision(), 9);
            assert_eq!(fresh.state_generation(), 1);
            assert_eq!(
                fresh.draft_session().context().history(),
                ["initial history"]
            );
        });
        drop(runtime);
    }

