    #[test]
    fn authoritative_not_committed_aborts_without_session_writeback_or_poison() {
        let runtime = test_runtime();

        runtime.block_on(async {
            let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
            let agent = test_owner_agent(test_mounted_runtime(), executor);
            let store = Arc::new(MountedStore::with_behavior(
                MountedStoreBehavior::IndeterminateNotCommitted,
            ));
            let live_aborts = Arc::new(AtomicUsize::new(0));
            let source = OwnerSource {
                revision: AtomicUsize::new(1),
            };
            let publication = prepare_owner_publication(
                &agent,
                &source,
                Arc::clone(&store),
                Arc::clone(&live_aborts),
                "mounted/not-committed",
                TurnFlow::Wait,
            )
            .await;

            let failure = match publication.publish().await {
                Ok(_) => panic!("NotCommitted cannot publish the candidate session"),
                Err(failure) => failure,
            };
            assert!(matches!(
                failure.source_error(),
                MountedPublicationFailureSource::NotCommitted
            ));
            assert!(failure.cleanup_acknowledged());
            assert_eq!(store.publish_calls.load(Ordering::SeqCst), 1);
            assert_eq!(store.resolve_calls.load(Ordering::SeqCst), 1);
            assert_eq!(store.state.lock().unwrap().revision, 0);
            assert_eq!(
                agent.state.read().await.session.context().history(),
                ["initial history"]
            );
            assert_eq!(agent.state.read().await.session_revision, 0);
            assert_eq!(live_aborts.load(Ordering::SeqCst), 1);
            assert!(!agent.cleanup_poisoned.load(Ordering::Acquire));
            drop(
                agent
                    .call("after-not-committed", "inspect")
                    .pin()
                    .await
                    .unwrap(),
            );
        });
        drop(runtime);
    }

    #[test]
    fn rejected_and_colliding_publications_abort_without_writeback() {
        let runtime = test_runtime();

        runtime.block_on(async {
            for (behavior, request_id, expected_resolves) in [
                (MountedStoreBehavior::Reject, "mounted/rejected", 0),
                (MountedStoreBehavior::Collision, "mounted/collision", 1),
            ] {
                let executor = Arc::new(TestExecutor::new(ExecutorMode::CompleteWithoutWire));
                let agent = test_owner_agent(test_mounted_runtime(), executor);
                let store = Arc::new(MountedStore::with_behavior(behavior));
                let live_aborts = Arc::new(AtomicUsize::new(0));
                let source = OwnerSource {
                    revision: AtomicUsize::new(1),
                };
                let publication = prepare_owner_publication(
                    &agent,
                    &source,
                    Arc::clone(&store),
                    Arc::clone(&live_aborts),
                    request_id,
                    TurnFlow::Wait,
                )
                .await;

                let failure = match publication.publish().await {
                    Ok(_) => panic!("a rejected candidate cannot be written back"),
                    Err(failure) => failure,
                };
                assert!(matches!(
                    failure.source_error(),
                    MountedPublicationFailureSource::Publication(_)
                ));
                assert!(failure.cleanup_acknowledged());
                assert_eq!(store.publish_calls.load(Ordering::SeqCst), 1);
                assert_eq!(
                    store.resolve_calls.load(Ordering::SeqCst),
                    expected_resolves
                );
                assert_eq!(store.state.lock().unwrap().revision, 0);
                assert_eq!(
                    agent.state.read().await.session.context().history(),
                    ["initial history"]
                );
                assert_eq!(agent.state.read().await.session_revision, 0);
                assert_eq!(live_aborts.load(Ordering::SeqCst), 1);
                assert!(!agent.cleanup_poisoned.load(Ordering::Acquire));
                drop(
                    agent
                        .call("after-rejection", "inspect")
                        .pin()
                        .await
                        .unwrap(),
                );
            }
        });
        drop(runtime);
    }
